/* register: OTP block panel */
.rf__locked{display:grid;gap:8px;padding:16px;border-radius:14px;background:var(--dk-tint-warn, #fff7ed);border:1px solid var(--dk-bd-warn, #fed7aa);margin:8px 0 4px;text-align:center;justify-items:center}
.rf__locked>b{font-size:.98rem}
.rf__locked>span{font-size:.86rem;color:var(--gray);line-height:1.45}
.rf__locked .btn{margin-top:4px}
.rf__locked .rf__otpmsg{margin:0}

/* detail modals: key/value sections + lists */
.dkv{display:grid;gap:14px}
.dkv__sect{display:grid;gap:6px;padding:12px 14px;border:1px solid var(--line);border-radius:12px;background:var(--dk-surface-2, #f7fafe)}
.dkv__sect>b{font-size:.74rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--gray2);margin-bottom:2px}
.dkv__row{display:flex;justify-content:space-between;gap:12px;font-size:.86rem}
.dkv__row span{color:var(--gray)}
.dkv__row b{text-align:right;min-width:0;word-break:break-word}
.dkv__list{list-style:none;margin:0;padding:0;display:grid;gap:4px}
.dkv__list li{display:grid;gap:2px;padding:8px 10px;border-radius:10px;background:var(--dk-surface, #fff);border:1px solid var(--line)}
.dkv__list li b{font-size:.86rem;font-weight:700}
.dkv__list li span{font-size:.78rem;color:var(--gray);display:inline-flex;align-items:center;gap:4px;flex-wrap:wrap}
.dkv__list li span svg{width:12px;height:12px}
.dkv__doc{border-radius:10px;background:var(--dk-surface, #fff);border:1px solid var(--line);overflow:hidden}
.dkv__doc+.dkv__doc{margin-top:6px}
.dkv__doc-h{display:flex;align-items:center;gap:8px;width:100%;padding:9px 12px;border:none;background:transparent;font-size:.86rem;font-weight:700;color:var(--ink);cursor:pointer;text-align:left}
.dkv__doc-h svg{width:15px;height:15px;flex:none}
.dkv__doc-h span{flex:1;min-width:0}
.dkv__doc-img{display:block;width:100%;max-height:420px;object-fit:contain;background:var(--dk-surface-2, #f1f4f9)}
.dkv__doc-frame{display:block;width:100%;height:420px;border:none;border-top:1px solid var(--line)}

/* seller client detail */
.pclient--btn{cursor:pointer;transition:.14s}
.pclient--btn:hover{border-color:var(--b300);background:var(--b50)}
.pclient--btn:focus-visible{outline:2px solid var(--b600);outline-offset:2px}
.cdet{display:grid;gap:12px}
.cdet__head{display:flex;align-items:center;gap:12px}
.cdet__m{display:grid;gap:2px;min-width:0}
.cdet__m b{font-size:1rem}
.cdet__m span{font-size:.84rem;color:var(--gray)}
.cdet__m small{font-size:.74rem;color:var(--gray2)}
.cdet__notes{margin:0;padding:10px 12px;border-radius:10px;background:var(--dk-surface-2, #f7fafe);font-size:.84rem;line-height:1.45;white-space:pre-line}
.cdet__stats{display:flex;flex-wrap:wrap;gap:6px}
.cdet__stats span{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;background:var(--b50);color:var(--dk-acc-strong, var(--b700));font-size:.78rem;font-weight:700}
.cdet__stats svg{width:14px;height:14px}
.cdet__chats{display:flex;flex-wrap:wrap;gap:8px}
.cdet .segs{width:100%}
.cdet .segs .seg{flex:1 1 auto}

/* ── wp-ad ── */
/* seller profile: section icon badges, identity card, fixed-column facts */
.ppanel__t{display:flex;align-items:center;gap:10px;min-width:0}
.pico{width:36px;height:36px;flex:none;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--grad);box-shadow:0 6px 14px -6px rgba(37,99,235,.55)}
.pico svg{width:18px;height:18px;stroke-width:2}
.pident{display:grid;gap:18px}
.pident__card{display:flex;align-items:center;gap:18px;padding:18px 20px;border-radius:18px;background:linear-gradient(135deg,var(--b50) 0%,var(--dk-surface, #fff) 60%);border:1px solid var(--line)}
.pident__card .phup{margin:0}
.pident__card .phup__av{width:88px;height:88px;border:0;padding:3px;background:var(--grad);box-shadow:0 8px 18px -8px rgba(37,99,235,.6)}
.pident__card .phup__av img,.pident__card .phup__av>span{border-radius:50%;background:var(--dk-surface, #fff)}
.pident__card .phup__av>span{width:100%;height:100%;display:grid;place-items:center;font-weight:800;font-size:1.25rem;color:var(--dk-acc, var(--b600))}
.pident__m{display:grid;gap:6px;min-width:0}
.pident__m>b{font-family:var(--fd);font-size:1.25rem;letter-spacing:-.02em;line-height:1.2}
.pident__role{font-size:.82rem;font-weight:700;color:var(--dk-acc, var(--b600))}
.pident__chips{display:flex;flex-wrap:wrap;gap:6px 8px;margin-top:2px}
.pident__chips span{display:inline-flex;align-items:center;gap:6px;padding:6px 11px;border-radius:999px;background:var(--dk-surface, #fff);border:1px solid var(--line);font-size:.8rem;font-weight:600;color:var(--ink);max-width:100%}
.pident__chips span svg{width:14px;height:14px;stroke:var(--dk-acc, var(--b600));flex:none}
.pident__chips span.miss{color:var(--gray2);border-style:dashed}
.pident__chips span.miss svg{stroke:var(--gray2)}
.pkv--cols{grid-template-columns:repeat(3,minmax(0,1fr));gap:14px 18px}
.pkv--cols .pkv__i{padding:12px 14px;border-radius:12px;background:var(--dk-surface-2, #f7fafe);min-width:0}
.pkv--cols .pkv__i b{display:block;font-size:.95rem;line-height:1.4;word-break:break-word;white-space:pre-line}
.pkv--cols .pkv__i--wide{grid-column:1 / -1}
.pkv--cols .pkv__i--empty b{color:var(--gray2);font-weight:600}
.pkv__lbl{display:block;font-size:.72rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--gray2);margin:0 0 8px}
.pdays{display:inline-flex;flex-wrap:wrap;align-items:center;gap:4px}
.pdays i{font-style:normal;font-size:.74rem;font-weight:700;padding:4px 8px;border-radius:8px;background:var(--dk-surface, #fff);border:1px solid var(--line);color:var(--gray2)}
.pdays i.on{background:var(--b100);border-color:transparent;color:var(--dk-acc-strong, var(--b700))}
.pdays em{font-style:normal;font-weight:800;margin-left:6px;font-variant-numeric:tabular-nums}
.pstate{display:inline-flex;align-items:center;gap:6px;font-weight:700}
.pstate svg{width:15px;height:15px}
.pstate--on{color:var(--ok)}
.pstate--off{color:var(--dk-txt-warn, #b45309)}
.cform__row3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
@media (max-width:900px){.cform__row3{grid-template-columns:1fr 1fr}.pkv--cols{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:560px){
  .cform__row3{grid-template-columns:1fr}
  .pkv--cols{grid-template-columns:1fr}
  .pident__card{flex-direction:column;align-items:flex-start;padding:16px}
  .pident__chips span{font-size:.76rem}
}
.pident__card .phup__av{cursor:default}

/* ── wp-ae ── */
/* selects: a real, boxed control everywhere (was bare text outside .fld) */
.dsel__btn{background:var(--dk-surface-2, #F7FAFE);border-radius:14px;padding:12px 13px 12px 15px;min-height:48px;box-shadow:inset 0 0 0 1.5px var(--line);transition:box-shadow .18s,background .18s}
.dsel__btn:hover{box-shadow:inset 0 0 0 1.5px var(--b300);background:var(--dk-surface, #fff)}
.dsel[data-open="true"] .dsel__btn,.dsel__btn:focus-visible{outline:none;box-shadow:inset 0 0 0 1.5px var(--b400);background:var(--dk-surface, #fff)}
/* …and inside a dialog it needs a stronger one. The default pairing is an
   #F7FAFE fill with an #E4EBF5 hairline, which reads fine on the page's own
   off-white ground but disappears against the modal card, which is pure
   white: on the light theme the control had no visible edge at all and the
   client could not see where the dropdown was. A darker border only there,
   and only as far as the modal body reaches. The dark theme keeps the
   neutral border it already has for this job.

   Placed after .dfrow's rule above, which sets this same border to
   transparent for the document rows — equal specificity, so the later of
   the two wins and a select in a dialog is outlined even there. */
.amodal__b .dsel__btn{box-shadow:inset 0 0 0 1.5px var(--dk-bd-neutral, #C7D5E8)}
.amodal__b .dsel__btn:hover{box-shadow:inset 0 0 0 1.5px var(--b300)}
.amodal__b .dsel[data-open="true"] .dsel__btn,.amodal__b .dsel__btn:focus-visible{box-shadow:inset 0 0 0 1.5px var(--b400)}
/* chevron in a soft round badge so the control reads as a dropdown */
.dsel__cv{box-sizing:border-box;width:24px;height:24px;border:0;border-radius:50%;background:var(--b100);position:relative;transform:none;margin:0;transition:background .18s}
.dsel__cv::after{content:"";position:absolute;left:50%;top:50%;width:7px;height:7px;border-right:2px solid var(--dk-acc, var(--b600));border-bottom:2px solid var(--dk-acc, var(--b600));transform:translate(-50%,-65%) rotate(45deg);transition:transform .22s}
.dsel[data-open="true"] .dsel__cv{background:var(--b200);transform:none;margin:0}
.dsel[data-open="true"] .dsel__cv::after{transform:translate(-50%,-30%) rotate(-135deg)}
.dsel__val--ph{color:var(--gray2);font-weight:500}
.dsel__menu{box-shadow:var(--s3),0 0 0 1px var(--line)}
/* inside a filter field (.fld) the field itself is the box */
.fld .dsel__btn{background:transparent;border-radius:0;padding:8px 0;margin-block:-8px;min-height:0;box-shadow:none}
.fld .dsel__btn:hover,.fld .dsel[data-open="true"] .dsel__btn{background:transparent;box-shadow:none}
.fld .dsel__cv{width:20px;height:20px}
/* compact in toolbars and list rows */
.lfilters .dsel__btn,.audit__filters .dsel__btn,.audit__hact .dsel__btn,.aitem__r .dsel__btn,.ccq__act .dsel__btn,.ppanel__h .dsel__btn{padding:8px 10px 8px 13px;min-height:40px;border-radius:12px;font-size:.88rem}
.lfilters .dsel{flex:0 1 220px;width:auto}
.aitem__r .dsel,.audit__hact .dsel,.ppanel__h .dsel{width:auto;min-width:170px}
.lfilters .dsel__cv,.audit__filters .dsel__cv,.audit__hact .dsel__cv,.aitem__r .dsel__cv,.ppanel__h .dsel__cv{width:20px;height:20px}
/* the other pickers get the same visible frame */
.mpick__btn{box-shadow:inset 0 0 0 1.5px var(--line)}
.ssel__ctrl{background:var(--dk-surface-2, #F7FAFE);border-color:transparent;box-shadow:inset 0 0 0 1.5px var(--line);border-radius:14px}
.ssel__ctrl:hover{border-color:transparent;box-shadow:inset 0 0 0 1.5px var(--b300);background:var(--dk-surface, #fff)}

/* ── wp-af ── */
/* meeting: the recording picker / "recording ready" panels must stay on
   screen — mtgToast fades OUT at the end (it is for toasts). */
@keyframes mtgRise{from{opacity:0;transform:translate(-50%,10px)}to{opacity:1;transform:translate(-50%,0)}}
.mtg__recpick,.mtg__recdone{animation:mtgRise .3s ease both;animation-fill-mode:both;transform:translate(-50%,0);opacity:1}
.mtg__recdone{z-index:8}
.mtg__recdone .btn,.mtg__recpick .btn{white-space:nowrap}
@media (prefers-reduced-motion:reduce){.mtg__recpick,.mtg__recdone{animation:none}}

/* ── wp-ag ── */
/* identity: MyID primary card, privacy note */
.idv__prov--main{border-color:var(--b300);background:linear-gradient(135deg,var(--b50),var(--dk-surface, #fff))}
.idv__prov b{display:flex;align-items:center;gap:8px}
.idv__tag{font-style:normal;font-size:.62rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;padding:3px 7px;border-radius:999px;background:var(--grad);color:#fff}
.idv__privacy{grid-column:1 / -1;margin:0;font-size:.78rem}
.ppanel__t .tfa__on{margin-left:4px}

/* ── wp-ah ── */
/* T0-10: unverified marks + admin two-mode setting */
.advcard__badge--un{background:var(--dk-surface-2, #f1f4f9);color:var(--gray);border:1px dashed var(--line)}
.advpick__un{font-style:normal;font-size:.68rem;font-weight:700;color:var(--gray2);padding:2px 7px;border-radius:999px;border:1px dashed var(--line);white-space:nowrap}
.lprof__vf--un{background:var(--dk-surface-2, #f1f4f9);color:var(--gray);border:1px dashed var(--line)}
.unvmode{display:grid;gap:10px}
.unvmode__opt{display:flex;align-items:flex-start;gap:12px;padding:14px 16px;border:1.5px solid var(--line);border-radius:14px;cursor:pointer;transition:.15s;background:var(--dk-surface, #fff)}
.unvmode__opt:hover{border-color:var(--b300)}
.unvmode__opt.on{border-color:var(--b600);background:var(--b50)}
.unvmode__opt input{position:absolute;opacity:0;width:0;height:0}
.unvmode__dot{width:20px;height:20px;flex:none;border-radius:50%;border:2px solid var(--b300);margin-top:1px;display:grid;place-items:center;transition:.15s}
.unvmode__opt.on .unvmode__dot{border-color:var(--b600);background:var(--b600);box-shadow:inset 0 0 0 4px var(--dk-surface, #fff)}
.unvmode__m{display:grid;gap:3px}
.unvmode__m b{font-size:.92rem}
.unvmode__m small{font-size:.8rem;color:var(--gray);line-height:1.4}

/* ── wp-ai ── */
/* dashboard hero: the completeness ring is a div inside .advhero__done — keep it a centred ring, not a flex column */
.advhero__done>.ring{display:grid;place-items:center;flex-direction:row;gap:0}
.ring{isolation:isolate}
.ring::before{background:var(--b900);z-index:0}
.ring b{z-index:1;color:#fff;line-height:1}
/* locked seller routes render chrome only */
.portal--gated{display:flex;align-items:center;justify-content:center;min-height:40vh;color:var(--gray)}

/* ── wp-aj ── */
/* 2FA: the active method as a highlighted card */
.tfa__method{display:flex;align-items:center;gap:14px;padding:14px 16px;border-radius:14px;margin:0 0 12px;border:1.5px solid var(--b300);background:linear-gradient(135deg,var(--b50),var(--dk-surface, #fff));flex-wrap:wrap}
.tfa__method-ic{width:42px;height:42px;flex:none;display:grid;place-items:center;border-radius:12px;background:var(--grad);color:#fff;box-shadow:0 6px 14px -6px rgba(37,99,235,.55)}
.tfa__method-ic svg{width:20px;height:20px}
.tfa__method--tg .tfa__method-ic{background:linear-gradient(135deg,#2AABEE,#229ED9)}
.tfa__method>div{display:grid;gap:2px;min-width:0;flex:1;align-content:start}
.tfa__method small{font-size:.68rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--gray2)}
.tfa__method b{font-size:1rem;font-family:var(--fd)}
.tfa__method>div>span{font-size:.8rem;color:var(--gray);line-height:1.4}
.tfa__method>.tfa__on{flex:none}
@media (max-width:480px){.tfa__method>.tfa__on{order:-1;margin-left:auto}}

/* ── wp-ak ── */
/* seller response countdown on new-order cards (T1-10 §6) */
.rtimer{display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:999px;font-size:.76rem;font-weight:800;font-variant-numeric:tabular-nums;background:var(--b100);color:var(--dk-acc-strong, var(--b700))}
.rtimer svg{width:13px;height:13px}
.rtimer--warn{background:var(--dk-tint-warn, #fff4e5);color:var(--dk-txt-warn, #b45309);animation:rtPulse 1s ease-in-out infinite}
.rtimer--over{background:var(--dk-tint-err, #fdecec);color:var(--dk-txt-err, #c0392b)}
@keyframes rtPulse{50%{opacity:.6}}

/* ── wp-al ── */
/* T0-20 §4: working-hours notice in the order modal */
.bhnote{display:flex;align-items:flex-start;gap:8px;margin:0;padding:10px 12px;border-radius:12px;font-size:.82rem;line-height:1.45;background:var(--dk-tint-warn, #fff7ed);color:var(--dk-txt-warn, #9a3412);border:1px solid var(--dk-bd-warn, #fed7aa)}
.bhnote svg{width:15px;height:15px;flex:none;margin-top:2px}
.bhnote--ok{background:var(--b50);color:var(--dk-acc-strong, var(--b700));border-color:var(--b200)}

/* ── wp-am ── */
/* admin: working-hours calendar card (T0-20) */
.bcal{display:grid;gap:16px}
.bcal__sched{display:grid;gap:2px;padding:12px 14px;border-radius:12px;background:var(--b50)}
.bcal__k{font-size:.7rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--gray2)}
.bcal__sched b{font-size:.95rem}.bcal__sched small{font-size:.78rem;color:var(--gray)}
.bcal__sect{display:grid;gap:8px}
.bcal__chips{display:flex;flex-wrap:wrap;gap:6px}
.bcal__chip{display:inline-flex;align-items:center;gap:6px;padding:5px 6px 5px 11px;border-radius:999px;background:var(--dk-tint-warn, #fff4e5);color:var(--dk-txt-warn, #9a3412);font-size:.8rem;font-weight:700}
.bcal__chip button{width:20px;height:20px;border:0;border-radius:50%;background:rgba(0,0,0,.06);color:inherit;display:grid;place-items:center;cursor:pointer}
.bcal__chip button svg{width:11px;height:11px}
.bcal__add{display:grid;grid-template-columns:minmax(150px,200px) minmax(0,1fr) auto;gap:8px;align-items:center}
.bcal__add input{width:100%;border:0;background:var(--dk-surface-2, #F7FAFE);border-radius:14px;padding:12px 15px;font:inherit;font-size:.92rem;box-shadow:inset 0 0 0 1.5px var(--line)}
.bcal__add input:focus{outline:none;box-shadow:inset 0 0 0 1.5px var(--b400);background:var(--dk-surface, #fff)}
.bcal__res{display:grid;gap:6px;padding:12px 14px;border-radius:12px;border:1px solid var(--line);background:var(--dk-surface-2, #f7fafe)}
.bcal__res>div{display:flex;justify-content:space-between;gap:12px;font-size:.86rem}
.bcal__res span{color:var(--gray)}
.bcal__res b.ok{color:var(--ok)}.bcal__res b.off{color:var(--dk-txt-warn, #b45309)}
.bcal__res-main{padding-top:8px;margin-top:2px;border-top:1px dashed var(--line)}
.bcal__res-main b{font-size:1rem;color:var(--dk-acc-strong, var(--b700))}
@media (max-width:640px){.bcal__add{grid-template-columns:1fr}}

/* ── wp-an ── */
/* lawyer card: inline error under the CTA */
.advcard__err{display:flex;gap:8px;align-items:flex-start;margin-top:10px;padding:9px 11px;border-radius:10px;font-size:.78rem;line-height:1.4;background:var(--dk-tint-err, #fef2f2);color:var(--dk-txt-err, #b91c1c);border:1px solid var(--dk-bd-err, #fecaca)}
.advcard__err svg{width:14px;height:14px;flex:none;margin-top:2px}
.advcard__err a{color:inherit;font-weight:700;text-decoration:underline}

/* ── wp-ap ── */
/* directory card CTAs + preselected advocate banner on the services page */
.advcard__ctas{display:flex;gap:6px;align-items:center;flex-wrap:wrap;justify-content:flex-end}
.presel{display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:14px;border:1.5px solid var(--b300);background:linear-gradient(135deg,var(--b50),var(--dk-surface, #fff));margin-bottom:14px;flex-wrap:wrap}
.presel__av{width:40px;height:40px;flex:none;border-radius:50%;display:grid;place-items:center;background:var(--grad);color:#fff;font-weight:800;font-size:.9rem}
.presel>div{display:grid;gap:2px;flex:1;min-width:0;align-content:start}
.presel b{font-size:.95rem}.presel span{font-size:.82rem;color:var(--gray);line-height:1.4}

/* ── wp-aq ── */
/* card / profile: working-hours notice shown on "Choose" */
.advcard__note{display:flex;gap:8px;align-items:flex-start;flex-wrap:wrap;margin-top:10px;padding:10px 12px;border-radius:10px;font-size:.78rem;line-height:1.45;background:var(--dk-tint-warn, #fff7ed);color:var(--dk-txt-warn, #9a3412);border:1px solid var(--dk-bd-warn, #fed7aa)}
.advcard__note svg{width:14px;height:14px;flex:none;margin-top:2px}
.advcard__note span{flex:1 1 180px}
.advcard__note .btn{margin-left:auto}
.lprof__note{margin:10px 0 0;padding:10px 12px;border-radius:10px;font-size:.82rem;line-height:1.45;background:var(--dk-tint-warn, #fff7ed);color:var(--dk-txt-warn, #9a3412);border:1px solid var(--dk-bd-warn, #fed7aa)}

/* ── wp-ar ── */
/* "new version available" bar */
.verwatch{position:fixed;left:50%;bottom:calc(16px + env(safe-area-inset-bottom));transform:translateX(-50%);z-index:250;display:flex;align-items:center;gap:12px;padding:10px 12px 10px 16px;border-radius:999px;background:var(--b900);color:#fff;font-size:.86rem;font-weight:600;box-shadow:0 12px 32px rgba(3,16,43,.35);max-width:calc(100% - 24px)}
.verwatch .btn svg{width:15px;height:15px}

/* ── wp-meetings ── */
/* ── wp-meetings ── */
/* Meeting launcher (admin/meetings, portal/{advocate,lawyer}/meetings): form panel + history panel. */
.mlaunch{display:grid;gap:16px}
.mlist{display:grid;gap:14px}
.mlist__grp{display:grid;gap:8px}
.mlist__gl{display:inline-flex;align-items:center;gap:8px;font-size:.74rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--gray2)}
.mlist__dot{width:8px;height:8px;border-radius:50%;background:var(--ok);box-shadow:0 0 0 3px rgba(0,168,112,.18)}
.mlist__row{flex-wrap:wrap}
.mlist__row--live{border-color:rgba(0,168,112,.35)}
.mlist__ic{width:38px;height:38px;flex:none;display:grid;place-items:center;border-radius:12px;background:var(--dk-surface-2, #F2F6FC);color:var(--gray2)}
.mlist__ic.on{background:var(--grad);color:#fff;box-shadow:0 6px 14px -6px rgba(37,99,235,.55)}
.mlist__ic svg{width:18px;height:18px;stroke-width:2}
.mlist__m{flex:1;min-width:0;display:grid;gap:2px;align-content:start}
.mlist__m b{font-size:.92rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mlist__m span{font-size:.78rem;color:var(--gray)}
.mlist__row .btn svg{width:15px;height:15px}
@media (max-width:560px){.mlist__row .btn{width:100%;justify-content:center}}

/* Meetings page — "rich" hero + icon-built illustration (portal only) */
.mhero{background:linear-gradient(135deg,var(--b50) 0%,var(--dk-surface, #fff) 70%);border:1px solid var(--line);border-radius:var(--rx);padding:clamp(18px,3vw,26px);display:flex;align-items:center;gap:20px;margin-bottom:16px}
.mhero__ico{width:60px;height:60px;border-radius:16px;background:var(--grad);color:#fff;display:grid;place-items:center;flex:none;box-shadow:var(--sblue)}
.mhero__ico svg{width:28px;height:28px}
.mhero__t{flex:1;min-width:0}
.mhero__t h2{margin:0 0 4px}
.mhero__t p{margin:0;color:var(--gray);max-width:54ch;font-size:.92rem}
.mhero__art{width:66px;height:66px;position:relative;flex:none;display:none}
@media (min-width:860px){.mhero__art{display:block}}
.mhero__art-cal{width:66px;height:66px;border-radius:18px;background:var(--b100);color:var(--dk-acc, var(--b600));display:grid;place-items:center}
.mhero__art-cal svg{width:30px;height:30px}
.mhero__art-vid{position:absolute;bottom:-6px;right:-6px;width:30px;height:30px;border-radius:10px;background:var(--grad);color:#fff;display:grid;place-items:center;box-shadow:var(--s2)}
.mhero__art-vid svg{width:15px;height:15px}

/* Meetings layout: create-form | today's agenda | mini calendar, side by side */
.mgrid3{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:16px;align-items:start;margin-bottom:16px}
@media (max-width:1080px){.mgrid3{grid-template-columns:1fr}}
.magenda{display:flex;flex-direction:column;gap:2px}
.magenda__row{display:flex;align-items:center;gap:11px;padding:10px 4px;border-left:3px solid var(--b400);border-radius:0 10px 10px 0;background:var(--b50)}
.magenda__row+.magenda__row{margin-top:8px}
.magenda__t{font-size:.78rem;font-weight:800;color:var(--dk-acc-strong, var(--b700));min-width:42px}
.magenda__m{flex:1;min-width:0}
.magenda__m b{display:block;font-size:.87rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.magenda__m span{font-size:.76rem;color:var(--gray2)}

/* History as a table (portal "rich" mode) */
.tavatar{width:26px;height:26px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:.66rem;font-weight:800;color:#fff;flex:none;box-shadow:0 0 0 2px var(--dk-surface, #fff)}
.tavatar+.tavatar{margin-left:-8px}
.tavatar--more{background:var(--dk-surface-2, #EEF2F8);color:var(--gray2)}
.tavstack{display:inline-flex;align-items:center}
.ptable .fmticon{display:inline-flex;align-items:center;gap:6px}
.ptable .fmticon svg{width:15px;height:15px;stroke:var(--gray2)}

/* Call-center board: one-click video meeting with a client (CcMeetingButton). */
.ccmeet{display:inline-grid;place-items:center;width:34px;height:34px;border:0;border-radius:10px;background:var(--b100);color:var(--dk-acc-strong, var(--b700));cursor:pointer;transition:background .15s,color .15s,transform .15s}
.ccmeet:hover{background:var(--b600);color:#fff}
.ccmeet:disabled,.ccmeet.busy{opacity:.6;cursor:progress}
.ccmeet svg{width:16px;height:16px;stroke-width:2}
.ccmeet__err{display:block;margin-top:4px;font-size:.74rem;font-weight:600;color:var(--dk-txt-err, #C0392B)}

/* Meeting room: recording consent + who is recording. */
.mtg__recask{position:absolute;left:50%;bottom:22px;transform:translate(-50%,0);z-index:9;display:grid;gap:6px;padding:14px 16px;border-radius:16px;background:var(--dk-surface, #fff);color:var(--ink);box-shadow:var(--s3);max-width:min(460px,calc(100% - 24px));animation:mtgRise .3s ease both}
.mtg__recask b{display:flex;align-items:center;gap:8px;font-size:.92rem}
.mtg__recask b i{width:9px;height:9px;border-radius:50%;background:#E5484D;flex:none;animation:mtgBlink 1.2s infinite}
.mtg__recask>span{font-size:.78rem;color:var(--gray)}
.mtg__recask-btns{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}
.mtg__recask-btns .btn{white-space:nowrap}
.mtg__recask-btns .btn svg{width:15px;height:15px}
.mtg__recpill{position:absolute;top:10px;right:10px;z-index:2;display:inline-flex;align-items:center;gap:5px;padding:4px 9px;border-radius:999px;background:rgba(229,72,77,.92);color:#fff;font-size:.66rem;font-weight:800;letter-spacing:.08em;pointer-events:none}
.mtg__recpill i{width:7px;height:7px;border-radius:50%;background:#fff;animation:mtgBlink 1.2s infinite}
.mtg__tile--small .mtg__recpill{top:6px;right:6px;padding:3px 7px;font-size:.58rem}
.mtg__tile--pip .mtg__recpill{top:6px;right:6px;padding:3px 6px;font-size:.56rem}
.mtg__precchip{flex:none;display:inline-flex;align-items:center;gap:5px;padding:3px 8px;border-radius:999px;background:rgba(229,72,77,.22);color:#fecaca;font-size:.68rem;font-weight:700;white-space:nowrap}
.mtg__precchip i{width:6px;height:6px;border-radius:50%;background:#E5484D;animation:mtgBlink 1.2s infinite}
.mtg__toast--info{border-color:rgba(37,99,235,.55)}
@media (max-width:760px){.mtg__recask{bottom:12px}}
@media (prefers-reduced-motion:reduce){.mtg__recask{animation:none}.mtg__recpill i,.mtg__precchip i,.mtg__recask b i{animation:none}}

/* ── wp-notif ── */
/* Notifications: category tabs with unread badges, filters, rows with an "open" link (components/portal/NotificationsPanel.tsx) */
.ntrow{display:flex;align-items:stretch;gap:8px;min-width:0}
.ntrow .ntitem{flex:1;min-width:0}
.ntitem__top{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.ntitem__cat{flex:none;font-size:.62rem;padding:2px 7px}
.ntitem__cat--orders{background:var(--b100);color:var(--dk-acc-strong, var(--b700))}
.ntitem__cat--payments{background:var(--dk-tint-ok, #E1F6EE);color:var(--ok)}
.ntitem__cat--chat{background:var(--dk-tint-blue, #eff6ff);color:var(--dk-acc, #2563eb)}
.ntitem__cat--documents{background:var(--dk-tint-warn, #fff7ed);color:var(--dk-txt-warn, #c2410c)}
.ntitem__cat--system{background:var(--dk-surface-2, #EEF2F7);color:var(--gray2)}
.ntitem__cat--marketing{background:var(--dk-tint-err, #FDECEC);color:var(--dk-txt-err, #C0392B)}
.ntitem__go{align-self:center;flex:none;white-space:nowrap}
@media (max-width:560px){.ntrow{flex-direction:column;gap:6px}.ntitem__go{align-self:flex-end}}

/* Admin notifications: recipient picker (role tabs + searchable checkbox list) and fan-out progress (app/[locale]/admin/notifications/page.tsx) */
.nrcp{margin-bottom:18px;padding-bottom:18px;border-bottom:1px solid var(--line)}
.nrcp__lbl{font-size:.78rem;font-weight:700;letter-spacing:.03em;text-transform:uppercase;color:var(--gray2);margin-bottom:6px}
.nrcp__hint{margin:0 0 10px;font-size:.82rem;color:var(--gray);line-height:1.4}
.nrcp__bar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:10px}
.nrcp__list{max-height:300px;overflow:auto;border:1.5px solid var(--line);border-radius:14px;padding:6px;display:flex;flex-direction:column;gap:2px;background:var(--dk-surface, #fff)}
.nrcp__row{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:10px;cursor:pointer;color:var(--ink);font-size:.9rem;user-select:none;transition:background .12s}
.nrcp__row:hover{background:var(--dk-surface-2, var(--b50))}
.nrcp__row.on{background:var(--b50)}
.nrcp__row input{position:absolute;opacity:0;width:0;height:0;pointer-events:none}
.nrcp__cb{width:20px;height:20px;flex:none;display:grid;place-items:center;border-radius:6px;border:1.5px solid var(--line);background:var(--dk-surface, #fff);color:#fff;transition:background .12s,border-color .12s}
.nrcp__cb svg{width:13px;height:13px;stroke-width:3;opacity:0}
.nrcp__row.on .nrcp__cb{background:var(--b600);border-color:var(--b600)}
.nrcp__row.on .nrcp__cb svg{opacity:1}
.nrcp__row input:focus-visible+.nrcp__cb{box-shadow:0 0 0 3px var(--b200)}
.nrcp__m{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
.nrcp__m b{font-weight:700;font-size:.9rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.nrcp__m small{font-size:.76rem;color:var(--gray2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.nrcp__row .atag{flex:none}
.nrcp__sum{display:flex;justify-content:space-between;gap:10px;margin-top:8px;font-size:.82rem;color:var(--gray)}
.nrcp__sum b{color:var(--dk-acc, var(--b600))}
.nrcp__manual{margin-top:12px}
.nrcp__manual summary{cursor:pointer;font-size:.82rem;font-weight:600;color:var(--dk-acc, var(--b600));list-style:none}
.nrcp__manual summary::-webkit-details-marker{display:none}
.nrcp__manual summary:before{content:"+ "}
.nrcp__manual[open] summary:before{content:"− "}
.nrcp__manual input{width:100%;border:0;background:var(--dk-surface-2, #F7FAFE);border-radius:14px;padding:13px 15px;font-size:.95rem;margin-top:8px;color:var(--ink)}
.nrcp__manual input:focus{box-shadow:inset 0 0 0 1.5px var(--b400);background:var(--dk-surface, #fff);outline:none}
.nrcp__catnote{font-size:.8rem;line-height:1.4}
.nsend{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:12px 14px;border-radius:14px;background:var(--dk-surface-2, #F7FAFE)}
.nsend__bar{flex:1 1 140px;height:8px;border-radius:999px;background:var(--b100);overflow:hidden}
.nsend__bar i{display:block;height:100%;border-radius:999px;background:var(--grad);transition:width .2s}
.nsend__txt{font-size:.84rem;font-weight:700;color:var(--ink);white-space:nowrap}
.nsend__last{display:flex;flex-direction:column;gap:8px;margin-top:14px}

/* ── wp-login-anim ── */
/* ═══════════════ AUTH ENTRANCE v2 (login page) ═══════════════
   Layers on the entrance choreography above: glow orbs drifting over the
   brand photo, a shimmer on the headline's accent word, stats that glow as
   their count lands, ambient glow where the brand panel is hidden, a busy
   spinner on the submit button and a lift-away exit once signed in. */
.auth{--auth-pop:cubic-bezier(.34,1.35,.64,1)}

/* orbs: own absolutely-positioned layers between the photo and the mesh,
   screen-blended so they read as light on the photo, not paint. The photo
   layer keeps its own drift; nothing new animates on it. Sized in cqw
   (.auth__brand is an inline-size container) so they track the panel width:
   ~330px at 1440, the 240px floor at 1024. */
.auth__orbs{position:absolute;inset:0;overflow:hidden;pointer-events:none;mix-blend-mode:screen}
.auth__orb{position:absolute;aspect-ratio:1;border-radius:50%;opacity:0;will-change:transform,opacity;
  background:radial-gradient(circle,rgba(0,207,232,.55),rgba(0,166,230,.2) 38%,transparent 70%)}
.auth__orb--1{width:clamp(240px,44cqw,520px);right:-8%;top:4%;
  animation:authOrbIn 2s var(--auth-ease) .5s both,authOrb1 16s ease-in-out 2.5s infinite alternate}
.auth__orb--2{width:clamp(200px,34cqw,400px);right:12%;bottom:-6%;
  background:radial-gradient(circle,rgba(46,139,255,.6),rgba(22,104,240,.2) 40%,transparent 70%);
  animation:authOrbIn 2s var(--auth-ease) .8s both,authOrb2 19s ease-in-out 2.8s infinite alternate}
.auth__orb--3{width:clamp(120px,18cqw,220px);right:36%;top:24%;
  background:radial-gradient(circle,rgba(185,241,255,.5),rgba(0,207,232,.16) 42%,transparent 70%);
  animation:authOrbIn 2s var(--auth-ease) 1.1s both,authOrb3 13s ease-in-out 3.1s infinite alternate}

/* headline accent: gradient text with a slow highlight pass, once the
   blur-in above has settled (inline span → no layout change) */
.auth__h-acc{background:linear-gradient(100deg,#8FD8FF 0%,#00CFE8 30%,#E2F8FF 50%,#00CFE8 70%,#8FD8FF 100%);
  background-size:220% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;
  animation:authShine 5.5s linear 1.3s infinite}

/* stat numbers glow for a beat as their count lands (card rise 1.1s + i·.1s,
   count 1.4s). On the <b> only: CountUp reads the card's own animation. */
.auth__stat b{animation:authStatGlow 1.2s ease-out both;animation-delay:calc(2.5s + var(--i,0) * .1s)}

/* ≤980px the brand panel is gone: two soft orbs breathe behind the form
   instead. Clipped by their wrapper so nothing widens the page. */
.auth__amb{display:none;position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:0}
.auth__amb-orb{position:absolute;aspect-ratio:1;border-radius:50%;opacity:0;will-change:transform,opacity;
  background:radial-gradient(circle,rgba(22,104,240,.16),rgba(0,166,230,.07) 42%,transparent 70%)}
html[data-theme="dark"] .auth__amb-orb{background:radial-gradient(circle,rgba(46,139,255,.24),rgba(0,207,232,.09) 42%,transparent 70%)}
.auth__amb-orb--1{width:min(78vw,420px);top:-14vw;right:-22vw;
  animation:authOrbIn 1.6s var(--auth-ease) .2s both,authOrb1 18s ease-in-out 1.8s infinite alternate}
.auth__amb-orb--2{width:min(64vw,360px);bottom:-10vw;left:-24vw;
  animation:authOrbIn 1.6s var(--auth-ease) .5s both,authOrb2 21s ease-in-out 2.1s infinite alternate}
@media (max-width:980px){
  .auth__amb{display:block}
  .auth__main-in{position:relative;z-index:1}
}

/* form cascade, a touch quicker than v1 (the phone field is ready by ~.9s)
   and the button lands with a slight overshoot. --fx keeps scaling every
   delay so the 2FA swap still replays at a third of the pace. */
.auth__main .plogin__c--anim>:not(.cform),.auth__main .plogin__c--anim .cform>*{
  animation-duration:calc(.7s * max(var(--fx),.6))}
.auth__main .plogin__c--anim .cform>.btn{animation-timing-function:var(--auth-pop)}
.auth__main .plogin__c--anim>.logo{animation-delay:calc(.2s * var(--fx))}
.auth__main .plogin__c--anim>h1{animation-delay:calc(.28s * var(--fx))}
.auth__main .plogin__c--anim>.sub{animation-delay:calc(.36s * var(--fx))}
.auth__main .plogin__c--anim .cform>:nth-child(1){animation-delay:calc(.46s * var(--fx))}
.auth__main .plogin__c--anim .cform>:nth-child(2){animation-delay:calc(.53s * var(--fx))}
.auth__main .plogin__c--anim .cform>:nth-child(3){animation-delay:calc(.6s * var(--fx))}
.auth__main .plogin__c--anim .cform>:nth-child(4){animation-delay:calc(.67s * var(--fx))}
.auth__main .plogin__c--anim .cform>:nth-child(5){animation-delay:calc(.74s * var(--fx))}
.auth__main .plogin__c--anim .cform>:nth-child(6){animation-delay:calc(.81s * var(--fx))}
.auth__main .plogin__c--anim .cform>:nth-child(n+7){animation-delay:calc(.88s * var(--fx))}
.auth__main .plogin__c--anim>.plogin__alt{animation-delay:calc(.9s * var(--fx))}
.auth__main .plogin__c--anim>.plogin__note{animation-delay:calc(.98s * var(--fx))}
/* re-stated after the delays above (same specificity, order decides) so a
   message that appears later still answers at once */
.auth__main .plogin__c--anim .cform>.plogin__err,
.auth__main .plogin__c--anim .cform>.rf__otpmsg--err{animation:authErr .45s ease-out 0s both}
.auth__main .plogin__c--anim .cform>.rf__otpmsg:not(.rf__otpmsg--err){animation:fade .3s ease-out 0s both}

/* submit: spinner while the server works (the shine keeps sweeping so the
   button reads as busy, not stuck), a quiet face while locked */
.auth__main .plogin__c .btn--pri:disabled{cursor:not-allowed;box-shadow:none}
.auth__main .plogin__c .btn--pri:disabled:hover{background:var(--b600)}
.auth__main .plogin__c .btn--pri[aria-busy="true"]{cursor:progress;box-shadow:var(--sblue)}
.auth__main .plogin__c .btn--pri[aria-busy="true"]::before{transition:none;animation:authSweep 1.5s ease-in-out .2s infinite}
.auth__main .plogin__c .btn .spin{width:15px;height:15px;border-width:2px}

/* success: the form lifts away; a status line fades in underneath for as
   long as the next route takes */
.auth__main .plogin{position:relative}
.auth__main .plogin__c--leave{animation:authLeave .42s var(--auth-ease) both;pointer-events:none}
.plogin__exit{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;gap:10px;
  font-size:.92rem;font-weight:600;color:var(--gray);pointer-events:none;animation:fade .4s ease-out .3s both}
.plogin__exit .spin{width:20px;height:20px;border-color:rgba(22,104,240,.2);border-top-color:var(--dk-acc, var(--b600))}

@keyframes authOrbIn{from{opacity:0}to{opacity:1}}
@keyframes authOrb1{from{transform:translate3d(0,0,0) scale(1)}to{transform:translate3d(-9%,12%,0) scale(1.12)}}
@keyframes authOrb2{from{transform:translate3d(0,0,0) scale(1)}to{transform:translate3d(10%,-14%,0) scale(1.08)}}
@keyframes authOrb3{from{transform:translate3d(0,0,0) scale(1)}to{transform:translate3d(-16%,20%,0) scale(1.2)}}
@keyframes authShine{from{background-position:120% 0}to{background-position:-100% 0}}
@keyframes authStatGlow{0%{text-shadow:0 0 0 rgba(0,207,232,0)}35%{text-shadow:0 0 22px rgba(0,207,232,.75)}100%{text-shadow:0 0 0 rgba(0,207,232,0)}}
@keyframes authSweep{from{left:-70%}to{left:130%}}
@keyframes authLeave{from{opacity:1;transform:none}to{opacity:0;transform:translateY(-14px)}}
@media (prefers-reduced-motion:reduce){
  .auth__orb,.auth__amb-orb,.auth__h-acc,.auth__stat b,.auth__main .plogin__c--leave,.plogin__exit,
  .auth__main .plogin__c .btn--pri[aria-busy="true"]::before{animation:none!important}
  /* the orbs stay as still light; the form stays put and the router moves on at once */
  .auth__orb,.auth__amb-orb{opacity:1}
}

/* ── wp-tariffs ── */
/* plans: ATMOS auto-pay card */
.apay .ppanel__t{align-items:flex-start}
.apay .ppanel__t>div{display:grid;gap:2px;min-width:0}
.apay__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:4px 0 14px}
.apay__cell{display:grid;gap:3px;padding:12px 14px;border-radius:12px;background:var(--dk-surface-2, #f7fafe)}
.apay__cell span{font-size:.7rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--gray2)}
.apay__cell b{font-size:.95rem;word-break:break-word}
.apay__row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.apay__tg{flex:1 1 260px;display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:14px;border:1.5px solid var(--line);background:var(--dk-surface, #fff);cursor:pointer;text-align:left;font:inherit;color:var(--ink);font-size:.9rem;font-weight:600;transition:.15s}
.apay__tg:hover{border-color:var(--b300)}
.apay__tg[aria-checked="true"]{border-color:var(--b400);background:var(--b50)}
.apay__tg:disabled{opacity:.6;cursor:default}
.apay__sw{width:44px;height:26px;flex:none;border-radius:999px;background:var(--gray2);position:relative;transition:background .2s}
.apay__sw::after{content:"";position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.25);transition:transform .2s}
.apay__tg[aria-checked="true"] .apay__sw{background:var(--ok)}
.apay__tg[aria-checked="true"] .apay__sw::after{transform:translateX(18px)}
.apay__state{color:var(--dk-acc, var(--b600))}
.apay__tg[aria-checked="true"] .apay__state{color:var(--ok)}
.apay__local{font-size:.74rem;font-weight:500;color:var(--gray)}
.apay__note{display:flex;gap:8px;align-items:flex-start;margin:12px 0 0;padding:10px 12px;border-radius:10px;font-size:.8rem;line-height:1.45;color:var(--gray);background:var(--b50)}
.apay__note svg{width:15px;height:15px;flex:none;margin-top:2px;stroke:var(--dk-acc, var(--b600))}
@media (max-width:640px){.apay__grid{grid-template-columns:1fr}}

/* ── wp-batch ── */
/* ── CRM: lead filter bar, assignment, auto-distribution ── */
.pipe__tags{display:flex;flex-wrap:wrap;gap:4px;margin-top:4px}
.pipe__tags .atag{font-size:.66rem}
.lasgn{display:grid;gap:8px}
.lasgn__row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.lasgn__row .dsel{flex:1 1 180px;width:auto}
.lasgn__hint{margin:0;font-size:.76rem;color:var(--gray);line-height:1.4}
.lauto{display:grid;gap:12px}
.lauto__stats{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.lauto__stat{display:grid;gap:2px;padding:12px 14px;border-radius:12px;background:var(--dk-surface-2, #f7fafe);text-align:center}
.lauto__stat b{font-family:var(--fd);font-size:1.4rem;color:var(--dk-acc-strong, var(--b700))}
.lauto__stat span{font-size:.74rem;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--gray2)}
.lauto__list{list-style:none;margin:0;padding:0;display:grid;gap:4px;max-height:220px;overflow:auto}
.lauto__list li{display:flex;justify-content:space-between;gap:10px;padding:7px 10px;border-radius:9px;background:var(--dk-surface, #fff);border:1px solid var(--line);font-size:.82rem}
.lauto__bar{height:8px;border-radius:999px;background:var(--b100);overflow:hidden;margin-top:8px}
.lauto__bar i{display:block;height:100%;background:var(--grad);border-radius:999px;transition:width .3s}
.lauto__note{margin:0;padding:10px 12px;border-radius:10px;font-size:.78rem;line-height:1.45;background:var(--dk-tint-warn, #fff7ed);color:var(--dk-txt-warn, #9a3412);border:1px solid var(--dk-bd-warn, #fed7aa)}

/* ── admin services: tools, hints, edit modal ── */
.svcadm__hint{display:flex;gap:8px;align-items:flex-start;margin:0 0 12px;padding:9px 12px;border-radius:10px;font-size:.78rem;line-height:1.45;color:var(--gray);background:var(--b50)}
.svcadm__hint svg{width:14px;height:14px;flex:none;margin-top:2px}
.svcadm__hint--warn{background:var(--dk-tint-warn, #fff7ed);color:var(--dk-txt-warn, #9a3412)}
.svced{display:grid;gap:12px}
.svced__head{display:flex;flex-wrap:wrap;gap:6px}
.svced__slug{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.74rem;padding:3px 8px;border-radius:6px;background:var(--dk-surface-2, #f1f4f9);color:var(--gray)}
.svced__ctx{display:flex;flex-wrap:wrap;gap:6px 14px;padding:10px 12px;border-radius:10px;background:var(--b50);font-size:.78rem}
.svced__kv{display:inline-flex;gap:5px}
.svced__kv span{color:var(--gray2)}
.svced__kv b{font-weight:700}
.svced__sec{font-size:.72rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--gray2);margin-top:6px}
.svced__row{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(180px,100%),1fr));gap:12px}
.svced__fh{display:block;margin-top:4px;font-size:.72rem;color:var(--gray2)}
.svced__hint{margin:0;font-size:.78rem;color:var(--gray);line-height:1.45}
.svced__hint--warn{padding:9px 12px;border-radius:10px;background:var(--dk-tint-warn, #fff7ed);color:var(--dk-txt-warn, #9a3412)}
.svced__meta{border:0;padding:0;margin:0;display:grid;gap:12px;min-width:0}
.svced__meta:disabled{opacity:.55}
.svced__sec2{border-top:1px solid var(--line);padding-top:12px;margin-top:6px;display:grid;gap:6px}
.svced__acts{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap;margin-top:6px}
.aplan__hint{display:block;margin-top:4px;font-size:.74rem;color:var(--gray2)}
.aplan__only{font-size:.8rem}

/* ── dashboards: clickable stat tiles, filter bar, drill-down modal ── */
.stile{position:relative}
.stile--btn{cursor:pointer;text-align:left;font:inherit;color:inherit;transition:transform .15s,box-shadow .15s,border-color .15s}
.stile--btn:hover{transform:translateY(-2px);box-shadow:var(--s2);border-color:var(--b300)}
.stile--btn:focus-visible{outline:2px solid var(--b600);outline-offset:2px}
.stile__demo{position:absolute;top:10px;right:10px;font-style:normal;font-size:.62rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;padding:3px 7px;border-radius:999px;background:var(--dk-tint-warn, #fff4e5);color:var(--dk-txt-warn, #b45309)}
.stile__demo--static{position:static;margin-left:8px}
.stile__hint{display:block;font-size:.7rem;color:var(--gray2);margin-top:2px}
.drill{display:grid;gap:14px}
.drill__head{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap}
.drill__v{font-family:var(--fd);font-size:1.8rem;letter-spacing:-.02em;color:var(--dk-acc-strong, var(--b700))}
.drill__note{margin:0;padding:10px 12px;border-radius:10px;font-size:.8rem;line-height:1.45;background:var(--b50);color:var(--gray)}
.drill__sec{display:grid;gap:8px}
.drill__t{margin:0;font-size:.74rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--gray2)}
.drill__pct{margin-left:6px;font-size:.72rem;color:var(--gray)}
.drill__ok{color:var(--ok)}
.drill__warn{color:var(--dk-txt-warn, #b45309)}
.drill__err{color:var(--dk-txt-err, #c0392b)}
@media (max-width:760px){
  .lauto__stats{grid-template-columns:1fr 1fr}
}

/* ── wp-ccmeet ── */
.ccb__contact{display:flex;align-items:center;justify-content:space-between;gap:8px}
.ccmeet--sm{width:28px;height:28px;border-radius:8px}
.ccmeet--sm svg{width:15px;height:15px}
/* ── wp-iconsize ── */
.lasg{display:inline-flex;align-items:center;gap:4px;padding:2px 8px;border-radius:999px;background:var(--b50);color:var(--dk-acc-strong, var(--b700));font-size:.7rem;font-weight:700;max-width:100%;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.lasg--none{background:var(--dk-surface-2, #f1f5f9);color:var(--gray)}
.lasg--me{background:var(--grad);color:#fff}
.lasg>span{overflow:hidden;text-overflow:ellipsis}
.lasg svg,.lasgn__hint svg{width:14px;height:14px;flex:none}
/* Stat tiles rendered as <button>: drop the UA button chrome, keep each variant's own look. */
.stile--btn{appearance:none;-webkit-appearance:none;width:100%;margin:0;display:flex;flex-direction:column;align-items:flex-start}
.ktile.stile--btn{background:none;border:0;padding:6px 8px;margin:-6px -8px;width:calc(100% + 16px);border-radius:12px}
.ktile.stile--btn:hover{background:var(--b50);box-shadow:none;transform:none}
.castat__c.stile--btn,.amet__c.stile--btn{text-align:left}

/* ── wp-catov ── */
.atag--warn{background:var(--dk-tint-warn, #fff4e5);color:var(--dk-txt-warn, #b45309)}
.chip--muted{color:var(--gray);font-size:.78rem;padding:6px 12px}
.chip--muted.on{background:var(--dk-surface-2, #EEF2F7);border-color:transparent;color:var(--ink)}

/* ── wp-dashd ── */
.castat--4{grid-template-columns:repeat(auto-fit,minmax(min(200px,100%),1fr))}
.castat--2{grid-template-columns:repeat(auto-fit,minmax(min(170px,100%),1fr));margin-bottom:0}
.castat__c.stile--btn{gap:6px}
.castat__c .stile__hint{margin-top:0}

/* ── wp-uxfix ── */
/* ── LeadFilterBar: Select/DatePicker default to width:100%, which inside a
   flex row makes every filter take its own full line. Scoped to .lfilters so
   other .dsel/.mpick usages (forms etc.) keep their own width. ── */
.lfilters>.dsel,.lfilters>.mpick{flex:1 1 150px;width:auto;max-width:210px}
.lfilters>.svsel__search{flex:1 1 190px}
/* A kanban board that opts into filling the rest of the viewport (see
   .pipe__col below) has only whatever height this filter bar leaves it —
   tighter rhythm here means less of that budget goes to chrome. */
.lfilters{gap:8px;margin-bottom:12px}

/* ── Sidebar brand: the role badge ("Call-markaz yuristi" etc.) sits on its
   own line under the logo instead of squeezing into one row. ── */
.psb__brand{padding:16px 18px;display:flex;flex-direction:column;align-items:flex-start;gap:7px}
.psb__brand .psb__logo{padding:0}
.psb__role{margin-left:0;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* ── Kanban columns: bound height to whatever the viewport actually has left
   (was a flat 70vh that could run off-screen below the fold on shorter
   screens, forcing a page scroll before the column's own scrollbar ever
   showed); thin, unobtrusive scrollbar instead of the fat OS default. ── */
.pipe__col{max-height:min(70vh,calc(100vh - 320px))}
.pipe__cards,.ccb__col{scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.pipe__cards::-webkit-scrollbar,.ccb__col::-webkit-scrollbar{width:6px}
.pipe__cards::-webkit-scrollbar-thumb,.ccb__col::-webkit-scrollbar-thumb{background:var(--line);border-radius:99px}
.pipe__cards::-webkit-scrollbar-thumb:hover,.ccb__col::-webkit-scrollbar-thumb:hover{background:var(--gray2)}

/* ── Call-center lead board: cards were dominated by two full-width native
   selects stacked one above the other; put them side by side and tighten
   the card. ── */
.ccb__col{max-height:min(74vh,calc(100vh - 260px));overflow-y:auto}
.ccb__card{gap:6px}
.ccb__sels{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(90px,100%),1fr));gap:6px}
.ccb__sels .dsel__btn{padding:8px 10px;min-height:38px;font-size:.8rem}
.ccb__sels .dsel__cv{right:9px}

/* ── Notifications → recipient checklist: 300px showed ~5 of a couple
   hundred users; give it real room to scroll through. ── */
.nrcp__list{max-height:420px}

/* ── Single-value SearchSelect (UserSelect): a plain label + sub text + a
   clear button, instead of a multi-select chip. ── */
.ssel__single{display:flex;align-items:baseline;gap:8px;flex:1;min-width:0;overflow:hidden}
.ssel__single b{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ssel__single small{color:var(--gray2);font-size:.8rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ssel__single span[role=button]{flex:none;display:grid;place-items:center;cursor:pointer;color:var(--gray2);opacity:.7}
.ssel__single span[role=button]:hover{opacity:1;color:var(--dk-txt-err, #c0392b)}
.ssel__single span[role=button] svg{width:14px;height:14px}

/* ── Client profile: avatar next to the identity card + estimate box on the
   gift modal. ── */
.pkv__av{display:flex;align-items:center;gap:14px;margin-bottom:14px}
.pgift__est{display:flex;align-items:baseline;justify-content:space-between;gap:10px;padding:12px 14px;border-radius:12px;background:var(--b50);margin:-2px 0 2px}
.pgift__est b{font-family:var(--fd);font-size:1.15rem;color:var(--dk-acc, var(--b600))}
.pgift__est span{font-size:.78rem;color:var(--gray)}

/* ── Warranty/replacement: centered result alert instead of an inline note
   easy to miss at the bottom of a long form. ── */
.wres{display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px}
.wres__ic{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:var(--dk-tint-ok, #ecfdf5);color:var(--dk-txt-ok, #059669)}
.wres--err .wres__ic{background:var(--dk-surface-2, #fef2f2);color:var(--dk-txt-err, #dc2626)}
.wres__ic svg{width:26px;height:26px}
.wres__status{display:inline-flex;align-items:center;gap:6px;padding:5px 12px;border-radius:999px;background:var(--b100);color:var(--dk-acc-strong, var(--b700));font-size:.8rem;font-weight:700}

/* ── wp-chatfiles ── lexgo_frontend_doc_chat_update.md: the document chat
   carries files and voice notes, not only text. The attachment endpoint is
   participants-only, so every bubble here is fetched with the session token
   and held as an object URL — never a bare link the browser would 401 on. */
.schat__bar .schat__attach,.schat__bar .schat__mic,.schat__bar .schat__reccancel{width:46px;height:46px;border-radius:50%;flex:none;display:grid;place-items:center;cursor:pointer;transition:transform .15s,background .15s,color .15s}
.schat__bar .schat__attach,.schat__bar .schat__mic{border:1.5px solid var(--line);background:var(--dk-surface-2, #F7FAFE);color:var(--gray);box-shadow:none}
.schat__bar .schat__attach svg,.schat__bar .schat__mic svg,.schat__bar .schat__reccancel svg{stroke:currentColor}
.schat__bar .schat__attach:hover:not(:disabled),.schat__bar .schat__mic:hover:not(:disabled){color:var(--dk-acc, var(--b600));border-color:var(--b300);transform:none}
.schat__bar .schat__attach svg,.schat__bar .schat__mic svg,.schat__bar .schat__reccancel svg{width:19px;height:19px}
.schat__bar .schat__reccancel{border:0;background:var(--dk-tint-err, #FDECEC);color:var(--dk-txt-err, #C0392B);box-shadow:none}
/* The lock sits over the text input, which the attach button pushes right. */
.schat__bar .schat__barlock{left:88px}
.schat__bar--rec .schat__barlock{display:none}
.schat__rec{flex:1;display:flex;align-items:center;gap:10px;min-width:0;padding:13px 18px;border-radius:var(--pill);background:var(--dk-tint-err, #FDECEC);color:var(--dk-txt-err, #C0392B);font-weight:700;font-variant-numeric:tabular-nums}
.schat__rec i{width:9px;height:9px;border-radius:50%;background:currentColor;flex:none;animation:mtgBlink 1.2s infinite}
.schat__rec small{font-weight:600;opacity:.75;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.schat__attacherr{max-width:860px;width:100%;margin:0 auto;padding:8px 18px 0;font-size:.84rem;font-weight:600;color:var(--dk-txt-err, #C0392B)}

/* Attachment inside a bubble. A voice note plays inline; a file waits for a
   click so opening a long history doesn't pull down every document in it. */
.sattach{display:flex;align-items:center;gap:10px;min-width:0;max-width:100%}
.sattach--voice{display:block}
.sattach--voice audio{display:block;width:100%;max-width:260px;height:38px}
.sattach__wait{font-size:.84rem;color:var(--gray)}
.sattach--file{width:100%;display:flex;align-items:center;gap:8px;text-align:left;border:1px solid var(--line);background:var(--dk-surface-2, #F7FAFE);border-radius:12px;padding:9px 11px;color:inherit;transition:border-color .15s,background .15s}
.sattach--file:hover{border-color:var(--b300)}
.sattach__open{flex:1;min-width:0;display:flex;align-items:center;gap:10px;padding:0;border:0;background:none;color:inherit;text-align:left;cursor:pointer;font:inherit}
.sattach__open:disabled{opacity:.6;cursor:default}
.sattach__i{width:34px;height:34px;border-radius:9px;flex:none;display:grid;place-items:center;background:var(--b50);color:var(--dk-acc, var(--b600))}
.sattach__i svg{width:17px;height:17px}
.sattach__t{display:flex;flex-direction:column;min-width:0;flex:1}
.sattach__t b{font-size:.88rem;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sattach__t small{font-size:.76rem;color:var(--gray)}
.sbub--me .sattach--file{background:rgba(255,255,255,.14);border-color:rgba(255,255,255,.22)}
.sbub--me .sattach__i{background:rgba(255,255,255,.2);color:#fff}
.sbub--me .sattach__t small{color:rgba(255,255,255,.78)}
@media (max-width:520px){
  .schat__bar .schat__attach,.schat__bar .schat__mic,.schat__bar .schat__reccancel{width:42px;height:42px}
  .schat__bar .schat__barlock{left:78px}
  .schat__rec small{display:none}
}

/* ── wp-meetlimit ── LEXGO_MEETING_EXTENSION_FRONTEND_UPDATE.md: a document
   meeting is capped at 15 minutes, extended once for free and then only
   against a payment the client approves in Telegram — during which the call
   is paused rather than ended. These sit inside .mtg__stage, which carries
   its own dark palette in both themes, so they use --mtg-* / the same
   surface treatment as .mtg__recask rather than the --dk-* tokens. */
.mtg__left--low{color:#FBC15E;font-weight:700}
.mtg__left--paused{color:#FBC15E;font-weight:700;display:inline-flex;align-items:center;gap:6px}
.mtg__left--paused::before{content:"";width:8px;height:8px;border-radius:2px;background:currentColor;animation:mtgBlink 1.4s infinite}
.mtg__pause,.mtg__ext{position:absolute;left:50%;top:12px;transform:translate(-50%,0);z-index:11;display:grid;gap:6px;padding:14px 16px;border-radius:16px;background:var(--dk-surface, #fff);color:var(--ink);box-shadow:var(--s3);max-width:min(460px,calc(100% - 24px));animation:mtgRise .3s ease both}
.mtg__pause b,.mtg__ext b{display:flex;align-items:center;gap:8px;font-size:.92rem}
.mtg__pause b svg{width:17px;height:17px;color:var(--dk-txt-warn, #9a3412)}
.mtg__pause>span,.mtg__ext>span{font-size:.8rem;color:var(--gray)}
.mtg__pause small{font-size:.74rem;color:var(--gray2)}
/* The pause card must stay readable while the stage is being recorded, so it
   is opaque rather than a translucent scrim over the tiles. */
.mtg__pause{border-left:3px solid var(--dk-txt-warn, #d97706)}
.mtg__ext-mins{display:flex;flex-wrap:wrap;gap:6px;margin-top:4px}
.mtg__ext-mins button{border:1.5px solid var(--line);background:var(--dk-surface-2, #F7FAFE);color:var(--ink);border-radius:var(--pill);padding:7px 13px;font-size:.82rem;font-weight:700;cursor:pointer;transition:.15s}
.mtg__ext-mins button.on{background:var(--grad);border-color:transparent;color:#fff;box-shadow:var(--sblue)}
.mtg__ext-total{font-size:.95rem!important}
.mtg__ext-err{font-size:.78rem;font-weight:600;color:var(--dk-txt-err, #C0392B)}
/* The floating panel hides .mtg__timer wholesale, so the pause card is the
   only place a floating meeting can say it is waiting on a payment. */
.mtg--float .mtg__pause,.mtg--float .mtg__ext{bottom:10px;padding:10px 12px;max-width:calc(100% - 16px)}
.mtg--float .mtg__pause small{display:none}
.mtg--float .mtg__ext-mins{gap:4px;margin-top:2px}
.mtg--float .mtg__ext-mins button{padding:5px 9px;font-size:.76rem}

/* ── wp-newdoc ── lexgo_frontend_custom_doc_flows.md: the catalog can't
   cover every case, so the services page also offers a document written
   from scratch and a review of one the client already has. */
.ppanel__hact{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
/* Reading a document costs nothing — the charge is for filling one in. */
.svfree{display:flex;align-items:center;gap:8px;margin:0 0 14px;padding:11px 14px;border-radius:12px;font-size:.88rem;font-weight:700;background:var(--dk-tint-ok, #E9F9F1);color:var(--dk-txt-ok, #0B7A52);border:1px solid var(--dk-bd-ok, #BFEAD6)}
.svfree svg{width:17px;height:17px;flex:none}

/* Upload tiles in the new-document forms. */
.docpick{display:flex;align-items:center;gap:12px;width:100%;text-align:left;padding:13px 15px;border:1.5px dashed var(--line);border-radius:14px;background:var(--dk-surface-2, #F7FAFE);cursor:pointer;color:inherit;transition:border-color .15s,background .15s}
.docpick:hover{border-color:var(--b300)}
.docpick__i{width:40px;height:40px;border-radius:11px;flex:none;display:grid;place-items:center;background:var(--b50);color:var(--dk-acc, var(--b600))}
.docpick__i svg{width:19px;height:19px}
.docpick__t{display:flex;flex-direction:column;min-width:0;gap:2px}
.docpick__t b{font-size:.9rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.docpick__t small{font-size:.78rem;color:var(--gray)}
.docpick__row{display:flex;flex-wrap:wrap;gap:8px;margin-top:4px}
.doclist{list-style:none;margin:10px 0 0;padding:0;display:flex;flex-direction:column;gap:6px}
.doclist li{display:flex;align-items:center;gap:9px;padding:8px 11px;border:1px solid var(--line);border-radius:11px;background:var(--dk-surface, #fff);font-size:.85rem;min-width:0}
.doclist li>svg{width:16px;height:16px;flex:none;color:var(--dk-acc, var(--b600))}
.doclist li>span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.doclist li>button{border:0;background:none;padding:4px;cursor:pointer;color:var(--gray2);display:grid;place-items:center;border-radius:7px}
.doclist li>button:hover{color:var(--dk-txt-err, #C0392B);background:var(--dk-tint-err, #FDECEC)}
.doclist li>button svg{width:15px;height:15px}
@media (max-width:560px){
  .ppanel__hact{width:100%;justify-content:space-between}
}

/* ── wp-docchat ── The client's side of a document request: message the
   advocate who took the work, or ring them (three calls per document).
   SecureChat is full-height by default, so the embedded copy gets an
   explicit box to live in. */
.docchat{display:flex;flex-direction:column;gap:10px;width:100%;margin-top:6px}
.docchat__acts{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.docchat__acts small{margin-left:auto}
.docchat__box{height:min(460px,60vh);display:flex;flex-direction:column;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--dk-surface, #fff)}
.docchat__box>*{flex:1;min-height:0;height:auto}
.docchat__wait{display:flex;align-items:center;gap:8px;margin:6px 0 0;font-size:.85rem;color:var(--gray)}
.docchat__wait svg{width:16px;height:16px;flex:none}
.docreview{display:flex;flex-direction:column;gap:8px;width:100%;text-align:left;padding:12px 14px;border:1px solid var(--line);border-radius:14px;background:var(--dk-surface-2, #F7FAFE)}
.docreview label{font-size:.82rem;font-weight:700;color:var(--gray)}
.docreview__btns{display:flex;align-items:center;gap:10px;flex-wrap:wrap}

/* ── wp-ffold ── Files page: the grid item is a 3D folder that opens on
   hover — the back cover stays put, the sheets inside tilt out, and the
   front cover swings down. Adapted from a Tailwind original to this file's
   tokens; every colour is per-card through --ff-* so one folder shape can
   carry the whole file-type palette, and the name sits under the folder.
   The global prefers-reduced-motion rule already flattens these. */
.fmgr__grid{grid-template-columns:repeat(auto-fill,minmax(min(168px,100%),1fr));gap:22px 14px;padding-top:14px}
.ffcard{
  position:relative;display:flex;flex-direction:column;align-items:center;gap:2px;min-width:0;
  --ff-back:#D08C2E;--ff-front:#F0A93B;--ff-front-2:#FBBF24;
  --ff-s1:var(--dk-surface, #fff);--ff-s2:var(--dk-surface-2, #EEF2F7);--ff-s3:var(--dk-tip, #DDE3EC);
  --ff-glow-a:rgba(251,191,36,.55);--ff-glow-b:rgba(217,119,6,.45);
}
.ffcard--pdf{--ff-back:#B33A3E;--ff-front:#E05257;--ff-front-2:#F1777B;--ff-glow-a:rgba(241,119,123,.5);--ff-glow-b:rgba(179,58,62,.45)}
.ffcard--doc{--ff-back:#1B5FB8;--ff-front:#2F7DE1;--ff-front-2:#5AA0F5;--ff-glow-a:rgba(90,160,245,.5);--ff-glow-b:rgba(27,95,184,.45)}
.ffcard--sheet{--ff-back:#0B7A52;--ff-front:#13996A;--ff-front-2:#2FBB88;--ff-glow-a:rgba(47,187,136,.5);--ff-glow-b:rgba(11,122,82,.45)}
.ffcard--image{--ff-back:#6A3DE8;--ff-front:#8460F0;--ff-front-2:#A489F7;--ff-glow-a:rgba(164,137,247,.5);--ff-glow-b:rgba(106,61,232,.45)}
.ffcard--file{--ff-back:#2A6B78;--ff-front:#37899A;--ff-front-2:#4FAABD;--ff-glow-a:rgba(79,170,189,.5);--ff-glow-b:rgba(42,107,120,.45)}

/* The folder itself is the button, so the whole tile is one target. */
.ffcard__hit{width:100%;border:0;background:none;padding:0 0 4px;cursor:pointer;display:block;border-radius:18px}
.ffcard__hit:focus-visible{outline:2px solid var(--dk-acc, var(--b600));outline-offset:3px}
.ffold{position:relative;display:block;width:100%;aspect-ratio:3/2;perspective:1500px;transform-origin:bottom}

/* Back cover: the tab and its little notch are the two pseudo-elements. */
.ffold__back{position:absolute;inset:0;background:var(--ff-back);border-radius:16px;border-top-left-radius:0;transform-origin:top;transition:box-shadow .3s ease}
.ffold__back::after{content:"";position:absolute;bottom:99%;left:0;width:34%;height:13px;background:var(--ff-back);border-radius:13px 13px 0 0}
.ffold__back::before{content:"";position:absolute;top:-12px;left:calc(34% - 4px);width:13px;height:13px;background:var(--ff-back);clip-path:polygon(0 35%,0 100%,50% 100%)}

/* Paper inside — three sheets that fan out by increasing angles. */
.ffold__s{position:absolute;inset:4px;border-radius:13px;transform-origin:bottom;transition:transform .3s ease;box-shadow:0 1px 2px rgba(3,16,43,.06)}
.ffold__s--3{background:var(--ff-s3)}
.ffold__s--2{background:var(--ff-s2)}
.ffold__s--1{background:var(--ff-s1)}

/* Front cover: shorter than the box so the sheets peek out at the top. */
.ffold__front{
  position:absolute;left:0;right:0;bottom:0;height:calc(100% - 4px);
  background:linear-gradient(to top,var(--ff-front),var(--ff-front-2));
  border-radius:16px;border-top-right-radius:0;transform-origin:bottom;
  transition:transform .3s ease,box-shadow .3s ease;display:flex;align-items:flex-end;
}
.ffold__front::after{content:"";position:absolute;bottom:99%;right:0;width:62%;height:13px;background:var(--ff-front-2);border-radius:13px 13px 0 0}
.ffold__front::before{content:"";position:absolute;top:-9px;right:calc(62% - 4px);width:11px;height:11px;background:var(--ff-front-2);clip-path:polygon(100% 14%,50% 100%,100% 100%)}

/* The type badge rides on the front cover and tilts down with it. */
.ffold__tag{display:inline-flex;align-items:center;gap:5px;margin:0 0 9px 11px;padding:4px 9px;border-radius:999px;background:rgba(255,255,255,.22);color:#fff;font-size:.68rem;font-weight:800;letter-spacing:.04em;backdrop-filter:blur(2px)}
.ffold__tag svg{width:13px;height:13px;stroke:#fff}
.ffold__tag i{font-style:normal}

.ffcard:hover .ffold__back,.ffcard__hit:focus-visible .ffold__back{box-shadow:0 20px 40px rgba(3,16,43,.22)}
.ffcard:hover .ffold__s--3,.ffcard__hit:focus-visible .ffold__s--3{transform:rotateX(-20deg)}
.ffcard:hover .ffold__s--2,.ffcard__hit:focus-visible .ffold__s--2{transform:rotateX(-30deg)}
.ffcard:hover .ffold__s--1,.ffcard__hit:focus-visible .ffold__s--1{transform:rotateX(-38deg)}
.ffcard:hover .ffold__front,.ffcard__hit:focus-visible .ffold__front{
  transform:rotateX(-46deg) translateY(1px);
  box-shadow:inset 0 20px 40px var(--ff-glow-a),inset 0 -20px 40px var(--ff-glow-b);
}

/* Name and size sit under the folder, centred on it. */
.ffcard__name{max-width:100%;font-size:.85rem;font-weight:700;color:var(--ink);text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ffcard__meta{font-size:.74rem;color:var(--gray2)}

/* Star and menu float over the folder rather than taking a row of their own. */
.ffcard__star{position:absolute;top:6px;left:6px;z-index:3;width:18px;height:18px;border-radius:50%;background:var(--dk-txt-warn, #F5A623);display:grid;place-items:center;box-shadow:0 0 0 2px var(--dk-surface, #fff)}
.ffcard__star svg{width:10px;height:10px;stroke:#fff;fill:#fff}
.ffcard__more{position:absolute;top:4px;right:4px;z-index:3;border:0;width:26px;height:26px;border-radius:8px;background:rgba(255,255,255,.82);color:var(--gray);display:grid;place-items:center;cursor:pointer;opacity:0;transition:opacity .2s ease,background .15s ease}
.ffcard:hover .ffcard__more,.ffcard__more:focus-visible{opacity:1}
.ffcard__more:hover{background:#fff;color:var(--ink)}
.ffcard__more svg{width:16px;height:16px}
/* Touch has no hover, so the menu button is always there. */
@media (hover:none){.ffcard__more{opacity:1}}
@media (max-width:520px){.fmgr__grid{grid-template-columns:repeat(auto-fill,minmax(min(140px,100%),1fr))}.ffold__tag{margin-left:8px;padding:3px 7px;font-size:.63rem}}

/* ── wp-deditor2 ── Document workspace, second pass. The screenshot showed
   three problems the first pass left: the three columns were all white, so
   they read as one surface; the top bar's middle sat empty while the
   document's identity hid inside the left panel; and SecureChat's full-page
   header (brand tile + title + two call buttons + an encrypted pill + a
   settings menu) was crushed into a 340px panel. Everything below is about
   giving each column its own edge and its own density, and taking away the
   things that had to fight for horizontal space. */

/* Columns. The editor keeps the document's own grey; the panels are
   surfaces above it, so they get a real edge rather than a hairline that
   vanishes against OnlyOffice's white chrome. */
.deditor__left{border-right:1px solid var(--line);box-shadow:1px 0 0 rgba(3,16,43,.03)}
.deditor__right{border-left:1px solid var(--line);box-shadow:-1px 0 0 rgba(3,16,43,.03)}
.deditor__left,.deditor__right{padding:14px;gap:12px}
.deditor__main{box-shadow:inset 0 1px 0 var(--line)}

/* Top bar: title + who it is for, then status, then actions. */
.deditor__ident{display:flex;flex-direction:column;min-width:0;line-height:1.25;gap:1px}
.deditor__title{max-width:34ch}
.deditor__sub{font-size:.75rem;color:var(--gray2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:34ch}
.deditor__status{display:flex;align-items:center;gap:8px;flex:none}
.deditor__save{display:inline-flex;align-items:center;gap:5px}
.deditor__save i{width:6px;height:6px;border-radius:50%;background:currentColor;flex:none}
.deditor__save--saving i{animation:mtgBlink 1.1s infinite}

/* ── Left panel ─────────────────────────────────────────────── */
.dclient{display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:14px;background:var(--dk-surface-2, #F5F8FD);border:1px solid var(--line);min-width:0}
.dclient__av{width:38px;height:38px;border-radius:12px;flex:none;display:grid;place-items:center;background:var(--grad);color:#fff;font-weight:800;font-size:.82rem;letter-spacing:.02em;box-shadow:var(--sblue)}
.dclient__t{display:flex;flex-direction:column;min-width:0;gap:2px}
.dclient__t b{font-size:.92rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dclient__tel{display:inline-flex;align-items:center;gap:5px;font-size:.8rem;font-weight:600;color:var(--dk-acc, var(--b600));text-decoration:none}
.dclient__tel:hover{text-decoration:underline}
.dclient__tel svg{width:13px;height:13px;flex:none}
.dclient__t small{font-size:.78rem}

.dstrip{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}
.dstrip__at{display:inline-flex;align-items:center;gap:5px;font-size:.76rem;color:var(--gray2)}
.dstrip__at svg{width:13px;height:13px;flex:none}

.dsec{display:flex;flex-direction:column;gap:8px;min-width:0}
.dsec__h{display:flex;align-items:center;gap:7px;margin:0;font-size:.74rem;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:var(--gray2)}
.dsec__h svg{width:14px;height:14px;flex:none;color:var(--dk-acc, var(--b600))}
.dsec__n{margin-left:auto;font-size:.74rem;color:var(--gray2);font-weight:700}
.dsec__acts{display:flex;flex-wrap:wrap;gap:6px}

/* The client's own words get a quote treatment — the one block on this
   panel that has to be read rather than scanned. */
.dneed{margin:0;padding:10px 12px 10px 14px;border-left:3px solid var(--dk-acc, var(--b600));border-radius:0 12px 12px 0;background:var(--dk-tint-blue, #F0F6FF);font-size:.87rem;line-height:1.55;color:var(--ink);white-space:pre-wrap;overflow-wrap:anywhere;max-height:220px;overflow-y:auto}

/* Filled-in answers: two columns that each keep their own minimum, instead
   of one row where a long value squeezes the label to nothing. */
.dfacts{margin:0;display:flex;flex-direction:column;gap:1px;border-radius:12px;overflow:hidden;border:1px solid var(--line)}
.dfacts__row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.3fr);gap:8px;padding:7px 10px;background:var(--dk-surface, #fff)}
.dfacts__row:nth-child(odd){background:var(--dk-surface-2, #F8FAFD)}
.dfacts dt{margin:0;font-size:.76rem;color:var(--gray2);overflow-wrap:anywhere}
.dfacts dd{margin:0;font-size:.8rem;font-weight:600;color:var(--ink);overflow-wrap:anywhere}

/* Label above value, left aligned: a service title here is a full sentence
   of legal Uzbek, and right-aligning it against a label made a ragged
   three-line block with the label floating beside its last row. */
.dmeta{display:flex;flex-direction:column;gap:2px;min-width:0}
.dmeta>span{font-size:.73rem;font-weight:700;letter-spacing:.03em;color:var(--gray2)}
.dmeta--who>span{display:inline-flex;align-items:center;gap:5px}
.dmeta--who svg{width:13px;height:13px;color:var(--dk-acc, var(--b600))}
.dmeta>b{min-width:0;font-size:.85rem;font-weight:700;line-height:1.4;overflow-wrap:anywhere}

.dchip{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:var(--dk-surface, #fff);border-radius:var(--pill);padding:6px 12px;font:inherit;font-size:.78rem;font-weight:700;color:var(--ink);cursor:pointer;transition:border-color .15s,color .15s}
.dchip:hover{border-color:var(--b300);color:var(--dk-acc, var(--b600))}
.dchip svg{width:14px;height:14px;flex:none}

/* ── Right panel ────────────────────────────────────────────── */
/* Four stacked icon+label columns did not fit beside the collapse chevron.
   One segmented row does, with the label next to the icon. */
.deditor__tabs{display:flex;gap:2px;flex:none;margin:0 0 10px;padding:3px;border-radius:var(--pill);background:var(--dk-surface-2, #F1F5FB);border-bottom:0}
.deditor__tabs button{position:relative;flex:1;min-width:0;display:flex;align-items:center;justify-content:center;gap:5px;border:0;border-bottom:0;background:none;border-radius:var(--pill);padding:7px 4px;font:inherit;font-size:.74rem;font-weight:700;color:var(--gray);cursor:pointer;transition:background .15s,color .15s}
.deditor__tabs button svg{width:15px;height:15px;flex:none}
.deditor__tabs button span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.deditor__tabs button.on{background:var(--dk-surface, #fff);color:var(--dk-acc, var(--b600));box-shadow:var(--s1)}
.deditor__tabdot{position:absolute;top:4px;right:6px;width:6px;height:6px;border-radius:50%;background:var(--ok);animation:mtgBlink 1.4s infinite}
/* The collapse chevron floated over the first tab; it takes its own row. */
.deditor__panelToggle{top:50%;right:-1px;transform:translateY(-50%);width:15px;height:52px;border-radius:8px 0 0 8px;background:var(--dk-surface-2, #EDF2FA);border:1px solid var(--line);border-right:0;box-shadow:none}
.deditor__panelToggle svg{width:12px;height:12px}
.deditor__panelToggle:hover{background:var(--b100);color:var(--dk-acc, var(--b600))}
.deditor__panelToggle--right{right:auto;left:-1px;border-radius:0 8px 8px 0;border:1px solid var(--line);border-left:0}

.dpane{display:flex;flex-direction:column;gap:10px;min-width:0}
/* A status card: icon, what the state is, one line of why it matters. */
.dstate{display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:14px;border:1px solid var(--line);background:var(--dk-surface-2, #F8FAFD);min-width:0}
.dstate__i{width:34px;height:34px;border-radius:11px;flex:none;display:grid;place-items:center;background:var(--dk-surface, #fff);color:var(--gray2);border:1px solid var(--line)}
.dstate__i svg{width:16px;height:16px}
.dstate__t{display:flex;flex-direction:column;min-width:0;gap:1px}
.dstate__t b{font-size:.86rem}
.dstate__t small{font-size:.76rem;color:var(--gray2);overflow-wrap:anywhere}
.dstate--ok .dstate__i{background:var(--dk-tint-ok, #E1F6EE);color:var(--dk-txt-ok, #0a7d55);border-color:transparent}
.dstate--idle .dstate__i{background:var(--dk-tint-warn, #FFF7ED);color:var(--dk-txt-warn, #B45309);border-color:transparent}
.dstate--live{border-color:var(--dk-bd-ok, #BFEAD6);background:var(--dk-tint-ok, #E9F9F1)}
.dstate--live .dstate__i{background:var(--ok);color:#fff;border-color:transparent}

.dppl{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px}
.dppl li{display:flex;align-items:center;gap:8px;font-size:.84rem;min-width:0}
.dppl li>span:last-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dppl__av{width:26px;height:26px;border-radius:9px;flex:none;display:grid;place-items:center;background:var(--b50);color:var(--dk-acc-strong, var(--b700));font-size:.68rem;font-weight:800}

.dids{margin:0;display:flex;flex-direction:column;gap:1px;border:1px solid var(--line);border-radius:12px;overflow:hidden}
.dids__row{display:flex;flex-direction:column;gap:2px;padding:8px 10px;background:var(--dk-surface, #fff)}
.dids__row:nth-child(odd){background:var(--dk-surface-2, #F8FAFD)}
.dids dt{margin:0;font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--gray2)}
.dids dd{margin:0;min-width:0}
.dids code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.76rem;color:var(--ink);overflow-wrap:anywhere;user-select:all}

/* One empty-state treatment for the whole panel. */
.dempty{display:flex;align-items:center;gap:8px;margin:0;padding:12px;border-radius:12px;background:var(--dk-surface-2, #F8FAFD);font-size:.82rem;color:var(--gray2);line-height:1.45}
.dempty svg{width:16px;height:16px;flex:none}
.dempty--lead{background:none;padding:0 0 2px}

/* ── SecureChat, embedded ────────────────────────────────────── */
/* No brand tile, no call buttons (the top bar starts the meeting), no
   settings menu, no close button — just a slim line saying the channel is
   live, then the messages. */
.schat--compact{height:auto}
.schat--compact .schat__head{gap:8px;padding:8px 12px;backdrop-filter:none;background:var(--dk-surface-2, #F8FAFD)}
.schat--compact .schat__i{width:26px;height:26px;border-radius:9px;box-shadow:none}
.schat--compact .schat__i svg{width:14px;height:14px}
.schat--compact .schat__t b{font-size:.8rem}
.schat--compact .schat__conn{font-size:.7rem}
.schat--compact .schat__body{padding:12px}
.schat--compact .schat__note{font-size:.7rem;padding:6px 10px;line-height:1.35}
.schat--compact .schat__bar{padding:10px 12px;gap:8px;max-width:none}
.schat--compact .schat__bar input{padding:10px 14px 10px 36px;font-size:.86rem}
.schat--compact .schat__bar .schat__barlock{left:64px}
.schat--compact .schat__bar .schat__attach,.schat--compact .schat__bar .schat__mic,.schat--compact .schat__bar .schat__reccancel,.schat--compact .schat__bar button{width:38px;height:38px}
.schat--compact .sbub{max-width:92%}
.schat--compact .sattach--voice audio{max-width:200px}

@media (max-width:640px){
  .deditor__sub{display:none}
  .deditor__status .deditor__save{display:none}
}

/* ── wp-mtgguard: meeting confidentiality ─────────────────────────────
   A browser cannot stop the operating system taking a screenshot, so this is
   the two-layer defence the enterprise meeting products use: a per-viewer
   watermark that makes any leaked frame traceable, and a shield that blanks
   the picture during the moments a capture happens (tab hidden, window
   blurred, screenshot key). Both live inside .mtg__stage, above every tile. */
/* Sparse and faint enough to talk through, dense enough that a photo of the
   screen still carries the name. The old version tiled twelve rotated lines
   across the picture and was unusable. */
.mtg__wm{position:absolute;inset:0;z-index:6;pointer-events:none;user-select:none;overflow:hidden}
.mtg__wm-p{position:absolute;inset:-10%;display:flex;flex-direction:column;justify-content:space-around;transition:transform 1.2s ease}
.mtg__wm[data-shift="1"] .mtg__wm-p{transform:translate(3%,2%)}
.mtg__wm[data-shift="2"] .mtg__wm-p{transform:translate(-2%,4%)}
.mtg__wm[data-shift="3"] .mtg__wm-p{transform:translate(2%,-3%)}
.mtg__wm-t{display:block;text-align:center;font-size:.8rem;font-weight:700;letter-spacing:.12em;white-space:nowrap;
  color:rgba(255,255,255,.055);transform:rotate(-12deg)}
/* The part that is always legible: one small chip, out of the way. */
.mtg__wm-chip{position:absolute;left:14px;bottom:12px;max-width:calc(100% - 28px);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  font-size:.66rem;font-weight:700;letter-spacing:.03em;color:rgba(255,255,255,.55);background:rgba(3,16,43,.4);
  border-radius:var(--pill);padding:3px 9px;backdrop-filter:blur(2px)}
.mtg__wm--compact .mtg__wm-chip{left:8px;bottom:8px;font-size:.6rem;padding:2px 7px}
/* The stage itself never shows a video frame while the shield is up: blurring
   and scaling the tiles means even a frame grabbed mid-transition is useless. */
.mtg__stage--guard .mtg__speaker,.mtg__stage--guard .mtg__grid{filter:blur(26px) brightness(.25);transform:scale(1.04)}
.mtg__stage--guard .mtg__wm{opacity:.45}
.mtg__shield{position:absolute;inset:0;z-index:30;display:grid;place-items:center;padding:18px;background:radial-gradient(120% 120% at 50% 40%,rgba(11,31,69,.94),rgba(2,6,16,.985));backdrop-filter:blur(8px);animation:mtgShield .12s ease both}
.mtg__shield-m{max-width:420px;text-align:center;display:flex;flex-direction:column;gap:8px}
.mtg__shield-m b{font-size:1.02rem;font-weight:800;color:#fff}
.mtg__shield-m span{font-size:.86rem;line-height:1.5;color:#cbd5e1}
.mtg__shield-m small{font-size:.74rem;line-height:1.5;color:rgba(203,213,225,.66)}
.mtg__shield[data-reason="capture"]{background:radial-gradient(120% 120% at 50% 40%,rgba(69,11,11,.95),rgba(16,2,2,.99))}
@keyframes mtgShield{from{opacity:0}to{opacity:1}}
@media (prefers-reduced-motion:reduce){.mtg__wm-p{transition:none}.mtg__shield{animation:none}}
@media (max-width:760px){.mtg__wm-t{font-size:.66rem}.mtg__wm-chip{font-size:.6rem}}

/* ── wp-urgent: Tezkor Advokat ────────────────────────────────────────
   Client module (components/portal/UrgentAdvocatePanel.tsx) and the
   call-center board (components/admin/UrgentAdvocateQueue.tsx). The module is
   a live service, so the hero and the card state carry that: a pulsing mark,
   an accent border on the picked card, and a summary that states the price,
   the length and what happens next before the submit button. */
.ua{display:flex;flex-direction:column;gap:18px}
.ua__hero{position:relative;display:flex;align-items:center;gap:16px;flex-wrap:wrap;padding:22px;border-radius:var(--rl);
  background:linear-gradient(120deg,var(--dk-acc-strong, var(--b700)),var(--dk-acc, var(--b600)) 55%,#7C3AED);color:#fff;box-shadow:var(--s2);overflow:hidden}
.ua__hero::after{content:"";position:absolute;inset:auto -60px -120px auto;width:260px;height:260px;border-radius:50%;background:rgba(255,255,255,.09)}
.ua__pulse{position:relative;flex:none;width:52px;height:52px;border-radius:16px;display:grid;place-items:center;background:rgba(255,255,255,.16);color:#fff}
.ua__pulse svg{width:26px;height:26px}
.ua__pulse::after{content:"";position:absolute;inset:-5px;border-radius:20px;border:2px solid rgba(255,255,255,.45);animation:uaPulse 2s ease-out infinite}
@keyframes uaPulse{0%{transform:scale(.9);opacity:.85}70%{transform:scale(1.18);opacity:0}100%{opacity:0}}
.ua__heromain{flex:1 1 220px;min-width:0}
.ua__title{margin:0;font-size:1.32rem;font-weight:800;line-height:1.25}
.ua__sub{margin:6px 0 0;font-size:.9rem;line-height:1.5;color:rgba(255,255,255,.82)}
.ua__meta{position:relative;display:flex;gap:18px;flex-wrap:wrap;margin:0;flex:none}
.ua__meta div{display:flex;flex-direction:column;gap:2px}
.ua__meta dt{font-size:.7rem;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:rgba(255,255,255,.62)}
.ua__meta dd{margin:0;font-size:.94rem;font-weight:800}

.ua__grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(224px,100%),1fr));gap:12px}
.uacard{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:8px;text-align:left;padding:16px 16px 44px;cursor:pointer;
  background:var(--dk-surface, #fff);border:1.5px solid var(--line);border-radius:var(--rl);box-shadow:var(--s1);transition:.2s;color:var(--ink)}
.uacard:hover{transform:translateY(-3px);box-shadow:var(--s2);border-color:var(--b300)}
.uacard.on{border-color:var(--b600);box-shadow:var(--sblue)}
.uacard__i{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:var(--b100);color:var(--dk-acc, var(--b600))}
.uacard__i svg{width:20px;height:20px}
.uacard.on .uacard__i{background:var(--b600);color:#fff}
.uacard__t{font-size:.95rem;font-weight:700;line-height:1.35}
.uacard__f{display:flex;flex-wrap:wrap;gap:6px}
.uacard__f em{display:inline-flex;align-items:center;gap:4px;font-style:normal;font-size:.72rem;font-weight:700;color:var(--gray);
  background:var(--dk-surface-2, #F2F6FC);border-radius:var(--pill);padding:3px 9px}
.uacard__f svg{width:12px;height:12px}
.uacard__lock{display:inline-flex;align-items:center;gap:5px;font-size:.72rem;font-weight:700;color:var(--dk-txt-warn, #b45309);
  background:var(--dk-warn-bg, #FEF3C7);border-radius:var(--pill);padding:3px 9px}
.uacard__lock svg{width:12px;height:12px}
.uacard__go{position:absolute;right:14px;bottom:14px;width:26px;height:26px;border-radius:50%;display:grid;place-items:center;
  background:var(--dk-surface-2, #F2F6FC);color:var(--gray);transition:.2s}
.uacard__go svg{width:14px;height:14px}
.uacard.on .uacard__go{background:var(--b600);color:#fff}

.ua__form{animation:uaIn .26s cubic-bezier(.2,.8,.2,1) both}
@keyframes uaIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.ua__count{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.ua__count b{min-width:34px;text-align:center;font-size:1.08rem;font-weight:800}
.ua__sum{display:flex;flex-direction:column;gap:8px;padding:14px;border-radius:var(--rl);background:var(--dk-surface-2, #F7FAFE);
  box-shadow:inset 0 0 0 1.5px var(--line)}
.ua__sumrow{display:flex;justify-content:space-between;align-items:center;gap:10px;font-size:.95rem;font-weight:700}
.ua__sumrow b{font-size:1.06rem;white-space:nowrap}
.ua__sumrow--sub{font-size:.84rem;font-weight:600;color:var(--gray)}
.ua__sumrow--sub span:first-child{display:inline-flex;align-items:center;gap:6px}
.ua__sumrow--sub svg{width:14px;height:14px}
.ua__next{display:flex;align-items:flex-start;gap:7px;margin:0;font-size:.82rem;line-height:1.5;color:var(--gray)}
.ua__next svg{width:14px;height:14px;flex:none;margin-top:2px;color:var(--ok)}
.ua__next--muted svg{color:var(--gray2)}

.ua__list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
.ua__row{display:flex;align-items:flex-start;gap:12px;padding:13px;border-radius:var(--rl);background:var(--dk-surface-2, #F7FAFE)}
.ua__rowi{flex:none;width:36px;height:36px;border-radius:11px;display:grid;place-items:center;background:var(--b100);color:var(--dk-acc, var(--b600))}
.ua__rowi svg{width:18px;height:18px}
.ua__rowm{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}
.ua__rowm b{font-size:.92rem;font-weight:700}
.ua__rowm span{font-size:.8rem;color:var(--gray);line-height:1.5;overflow-wrap:anywhere}
.ua__when{display:inline-flex;align-items:center;gap:5px;font-weight:600}
.ua__when svg{width:13px;height:13px;flex:none}
.ua__rowr{flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:7px}
.ua__st--claimed,.ua__st--completed{background:var(--dk-ok-bg, #E7F8F0);color:var(--ok)}

/* The dashboard tile that opens the module — a live service, so it gets the
   accent border and a breathing dot rather than another flat card. */
.cdact__i--live{border-color:var(--b300);background:linear-gradient(180deg,var(--b100),var(--dk-surface, #fff) 58%)}
.cdact__i--live .cdact__ico{position:relative;background:var(--b600);color:#fff}
.cdact__dot{position:absolute;top:-3px;right:-3px;width:10px;height:10px;border-radius:50%;background:var(--ok);
  box-shadow:0 0 0 2px var(--dk-surface, #fff);animation:uaBlink 1.8s ease-in-out infinite}
@keyframes uaBlink{0%,100%{opacity:1}50%{opacity:.35}}

/* ── Call-center board ───────────────────────────────────────────── */
.uaq__lead{margin:0 0 12px;font-size:.86rem;line-height:1.5}
.uaq__src{display:flex;align-items:center;gap:8px;min-height:48px;padding:0 15px;border-radius:14px;background:var(--dk-tint-blue, #E8F1FF);color:var(--dk-acc-strong, var(--b700));font-size:.9rem;font-weight:700;white-space:nowrap}
.uaq__src svg{width:16px;height:16px;flex:none}
.uaq__list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
.uaq__row{display:flex;align-items:flex-start;gap:12px;padding:14px;border-radius:var(--rl);background:var(--dk-surface-2, #F7FAFE);
  box-shadow:inset 0 0 0 1.5px transparent;transition:.18s}
.uaq__row--open{box-shadow:inset 0 0 0 1.5px var(--b300)}
.uaq__i{flex:none;width:38px;height:38px;border-radius:11px;display:grid;place-items:center;background:var(--b100);color:var(--dk-acc, var(--b600))}
.uaq__i svg{width:19px;height:19px}
.uaq__i--chat{background:var(--dk-ok-bg, #E7F8F0);color:var(--ok)}
.uaq__m{flex:1;min-width:0;display:flex;flex-direction:column;gap:4px}
.uaq__m>b{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:.94rem;font-weight:700}
.uaq__ch{display:inline-flex;align-items:center;gap:4px;font-style:normal;font-size:.7rem;font-weight:700;color:var(--gray);
  background:var(--dk-surface, #fff);border-radius:var(--pill);padding:3px 9px}
.uaq__ch svg{width:12px;height:12px}
.uaq__need{font-size:.85rem;line-height:1.5;color:var(--ink);display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.uaq__sub{font-size:.78rem;color:var(--gray);line-height:1.5;overflow-wrap:anywhere}
.uaq__when{display:inline-flex;align-items:center;gap:5px;font-size:.78rem;font-weight:700;color:var(--dk-acc, var(--b600))}
.uaq__when svg{width:13px;height:13px}
.uaq__r{flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:7px}
.uaq__acts{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}
.uaq__hint{display:inline-flex;align-items:center;gap:5px;font-size:.72rem;color:var(--gray2)}
.uaq__hint svg{width:12px;height:12px}
.uaq__st--open_pool{background:var(--dk-warn-bg, #FEF3C7);color:var(--dk-txt-warn, #b45309)}
.uaq__st--claimed{background:var(--dk-ok-bg, #E7F8F0);color:var(--ok)}
.uaq__when2{display:grid;grid-template-columns:1fr 1fr;gap:10px}

.docq__hint{margin:6px 0 0;font-size:.8rem;line-height:1.5;color:var(--gray)}
.oquote__row--sub{font-size:.8rem;color:var(--gray)}

@media (max-width:760px){
  .ua__hero{padding:18px}
  .ua__meta{gap:14px}
  .ua__grid{grid-template-columns:1fr}
  .ua__row,.uaq__row{flex-wrap:wrap}
  .ua__rowr,.uaq__r{flex-direction:row;align-items:center;width:100%;justify-content:space-between;flex-wrap:wrap}
  .uaq__when2{grid-template-columns:1fr}
}

/* ── wp-polish: card grids, the services filter bar, motion ───────────
   Three recurring defects this block fixes across the app:
     • grids sized so the last card wraps alone ("orphan") when one more
       would have fitted;
     • a filter that looked like two stray rows of chips;
     • buttons and dialogs appearing with no transition at all. */

/* 4 across where 3 used to fit — the track size itself lives with the rest
   of the .svfam rules above (and in their 980px media query), so the tablet
   override is not defeated by a later base rule. */
@media (min-width:1500px){.svfam__grid{grid-template-columns:repeat(auto-fill,minmax(min(232px,100%),1fr))}}

/* ── Services filter bar ─────────────────────────────────────────── */
.svfb{border:1.5px solid var(--line);border-radius:var(--rl);background:var(--dk-surface-2, #F7FAFE);padding:12px 14px 14px;margin-bottom:14px;transition:border-color .2s,box-shadow .2s}
.svfb--on{border-color:var(--b300);box-shadow:inset 0 0 0 1px var(--b200)}
.svfb__head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:10px}
.svfb__title{display:inline-flex;align-items:center;gap:7px;font-size:.8rem;font-weight:800;letter-spacing:.04em;text-transform:uppercase;color:var(--gray2)}
.svfb__title svg{width:15px;height:15px}
.svfb__n{font-style:normal;font-size:.68rem;font-weight:800;color:#fff;background:var(--b600);border-radius:var(--pill);padding:2px 7px;letter-spacing:0}
.svfb__clear{display:inline-flex;align-items:center;gap:5px;border:0;background:transparent;cursor:pointer;font-size:.8rem;font-weight:700;color:var(--gray);padding:4px 8px;border-radius:var(--pill);transition:.18s}
.svfb__clear:hover{background:var(--dk-surface, #fff);color:#E5484D}
.svfb__clear svg{width:13px;height:13px}
.svfb__groups{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(280px,100%),1fr));gap:12px 22px;align-content:start}
.svfb__g{display:grid;gap:7px;align-content:start;min-width:0}
.svfb__l{font-size:.74rem;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--gray2)}
.svfb__opts{display:flex;flex-wrap:wrap;gap:7px}
.svfopt{display:inline-flex;align-items:center;gap:7px;border:1.5px solid transparent;background:var(--dk-surface, #fff);color:var(--ink);
  border-radius:var(--pill);padding:7px 12px 7px 8px;font-size:.85rem;font-weight:600;cursor:pointer;white-space:nowrap;
  box-shadow:var(--s1);transition:transform .16s cubic-bezier(.2,.8,.2,1),border-color .16s,background .16s,color .16s,box-shadow .16s}
.svfopt:hover{transform:translateY(-1px);border-color:var(--b300)}
.svfopt:active{transform:translateY(0) scale(.98)}
.svfopt__i{width:22px;height:22px;border-radius:7px;display:grid;place-items:center;background:var(--dk-surface-2, #EEF4FD);color:var(--gray);flex:none;transition:.16s}
.svfopt__i svg{width:13px;height:13px}
.svfopt__n{font-style:normal;font-size:.72rem;font-weight:800;color:var(--gray2);background:var(--dk-surface-2, #EEF4FD);border-radius:var(--pill);padding:1px 7px;transition:.16s}
.svfopt.on{border-color:var(--b600);background:var(--b600);color:#fff;box-shadow:var(--sblue)}
.svfopt.on .svfopt__i{background:rgba(255,255,255,.2);color:#fff}
.svfopt.on .svfopt__n{background:rgba(255,255,255,.22);color:#fff}
/* An option that would return nothing is dimmed rather than hidden: the
   catalogue's shape is information too, and a row that reflows on every
   keystroke is worse than a greyed-out choice. */
.svfopt--empty{opacity:.45}
.svfopt--empty:hover{transform:none;border-color:transparent}
@media (max-width:620px){
  .svfb__groups{gap:12px}
  .svfopt{padding:6px 10px 6px 7px;font-size:.8rem}
}

/* ── Motion ──────────────────────────────────────────────────────────
   Buttons answer a press, dialogs arrive instead of blinking into place.
   All of it collapses under prefers-reduced-motion at the end of the file. */
.btn{transition:transform .16s cubic-bezier(.2,.8,.2,1),box-shadow .18s,background .18s,border-color .18s,color .18s,opacity .18s}
.btn:not([disabled]):not([aria-disabled]):active{transform:translateY(1px) scale(.985)}
.fchip{transition:transform .16s cubic-bezier(.2,.8,.2,1),background .2s,color .2s,box-shadow .2s}
.fchip:active{transform:scale(.97)}
.seg{transition:transform .16s cubic-bezier(.2,.8,.2,1),background .22s,color .22s,box-shadow .22s}
.seg:active{transform:scale(.98)}

/* The header bell when a notification lands. */
.ptop__bell{transition:transform .18s cubic-bezier(.2,.8,.2,1),background .18s}
.ptop__bell--pop{animation:bellPop .7s cubic-bezier(.2,.8,.2,1)}
@keyframes bellPop{
  0%{transform:none}
  15%{transform:rotate(-14deg) scale(1.1)}
  35%{transform:rotate(11deg) scale(1.08)}
  55%{transform:rotate(-7deg) scale(1.04)}
  75%{transform:rotate(4deg)}
  100%{transform:none}
}
.ntmore{margin-top:4px}

@media (prefers-reduced-motion:reduce){
  .btn,.fchip,.seg,.svfopt,.ptop__bell{transition:none!important}
  .btn:active,.fchip:active,.seg:active,.svfopt:active{transform:none!important}
  .ptop__bell--pop{animation:none}
}

/* The portal's own modal had no entrance of its own — only the scrim faded,
   so the panel blinked in at full size. Matches .amodal__c's pop. */
.pmodal__c{animation:pop .24s cubic-bezier(.2,.8,.3,1) both}
@media (prefers-reduced-motion:reduce){
  .pmodal__c,.amodal__c,.pmodal,.amodal{animation:none!important}
}

/* ── wp-polish2: inbox rows, tablet/laptop band ──────────────────── */

/* Secure-chat inbox. The rows carry a name and a time now, so they need the
   two-line layout every other list in the portal uses. */
.sinbox__item{position:relative;transition:transform .16s cubic-bezier(.2,.8,.2,1),background .18s,box-shadow .18s,border-color .18s}
.sinbox__item:hover{transform:translateX(2px)}
.sinbox__av{font-size:.82rem;font-weight:800;letter-spacing:.02em}
.sinbox__sub{display:inline-flex;align-items:center;gap:5px;flex-wrap:wrap}
.sinbox__sub svg{width:12px;height:12px;flex:none}
.sinbox__dot{opacity:.5}
.sinbox__new{width:9px;height:9px;border-radius:50%;background:var(--b600);flex:none;box-shadow:0 0 0 3px var(--b100);animation:sinboxPing 1.8s ease-in-out infinite}
@keyframes sinboxPing{0%,100%{opacity:1}50%{opacity:.4}}
.sinbox__item--new{background:var(--b50)}
.sinbox__item--new .sinbox__m b{font-weight:800}
.sinbox__newn{font-style:normal;font-size:.72rem;font-weight:800;color:#fff;background:var(--b600);border-radius:var(--pill);padding:3px 9px}

/* ── Tablet landscape and small laptops (iPad Pro, 13" MacBook) ──────
   Between 901px and 1200px the 252px sidebar plus the desktop page padding
   left the content column under 600px, so two-column panels and card grids
   were being squeezed rather than laid out. The sidebar and the gutters give
   the room back; nothing above 1200px changes. */
@media (min-width:901px) and (max-width:1200px){
  .portal{grid-template-columns:212px minmax(0,1fr)}
  .psb__link{padding:10px 11px;font-size:.86rem;gap:9px}
  .psb__logo{padding:14px 14px;font-size:1.1rem}
  .pbody{padding:18px}
  .pbody__in{gap:16px}
  .ppanel{padding:16px}
  /* Panels that ask for two fixed columns get one until there is room. */
  .pgrid2,.calwrap,.subs__layout{grid-template-columns:minmax(0,1fr)}
  .svfam__grid{grid-template-columns:repeat(auto-fill,minmax(min(168px,100%),1fr));gap:12px}
  .plans__grid{grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr))}
  .pcards{grid-template-columns:repeat(auto-fit,minmax(min(260px,100%),1fr))}
  .ua__grid{grid-template-columns:repeat(auto-fit,minmax(min(200px,100%),1fr))}
}

/* 13"–15" laptops: the content column is wide enough for the desktop layout
   but not for the 1560px reading width, which left the header and the cards
   stretched across the full screen. */
@media (min-width:1201px) and (max-width:1560px){
  .pbody{padding:clamp(20px,2.2vw,32px)}
}

/* ── wp-fix5: open document work, builder exit, floating meeting ─── */

/* Document work the client has started and not got back yet, shown on the
   cases page — where they look for "what is still open". */
.odw__lead{margin:0 0 12px;font-size:.85rem;line-height:1.5}
.odw__list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
.odw__row{display:flex;align-items:flex-start;gap:12px;padding:13px;border-radius:var(--rl);background:var(--dk-surface-2, #F7FAFE);
  box-shadow:inset 0 0 0 1.5px transparent;transition:box-shadow .18s}
.odw__row:hover{box-shadow:inset 0 0 0 1.5px var(--b200)}
.odw__i{flex:none;width:36px;height:36px;border-radius:11px;display:grid;place-items:center;background:var(--b100);color:var(--dk-acc, var(--b600))}
.odw__i svg{width:18px;height:18px}
.odw__m{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}
.odw__m b{font-size:.92rem;font-weight:700;line-height:1.35}
.odw__sub{font-size:.79rem;color:var(--gray);line-height:1.5;overflow-wrap:anywhere}
.odw__next{font-size:.81rem;color:var(--ink);line-height:1.5}
.odw__live{display:inline-flex;align-items:center;gap:5px;font-size:.76rem;font-weight:700;color:var(--ok)}
.odw__live svg{width:13px;height:13px}
.odw__acts{flex:none;display:flex;align-items:center;gap:8px}
.odw__wait{display:inline-flex;align-items:center;gap:5px;font-size:.76rem;font-weight:600;color:var(--gray2);white-space:nowrap}
.odw__wait svg{width:13px;height:13px}
/* Row actions on the documents list, so the chat and the download sit side by
   side instead of each inventing its own margin. */
.pcase__acts{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}
@media (max-width:640px){
  .odw__row{flex-wrap:wrap}
  .odw__acts{width:100%;justify-content:flex-start}
}

/* ── Builder exit ─────────────────────────────────────────────────── */
.docbuild__exit{margin-left:auto;display:inline-flex;align-items:center;gap:6px;border:1.5px solid var(--line);background:var(--dk-surface, #fff);
  color:var(--gray);border-radius:var(--pill);padding:7px 13px;font-size:.84rem;font-weight:700;cursor:pointer;
  transition:transform .16s cubic-bezier(.2,.8,.2,1),border-color .18s,color .18s,background .18s}
.docbuild__exit:hover{border-color:#f5b1b1;color:#dc2626;background:#fff5f5}
.docbuild__exit:active{transform:scale(.97)}
.docbuild__exit svg{width:14px;height:14px}
.dexit__lead{display:flex;align-items:flex-start;gap:11px;margin:0;font-size:.9rem;line-height:1.55;color:var(--ink)}
.dexit__i{flex:none;width:34px;height:34px;border-radius:11px;display:grid;place-items:center;
  background:var(--dk-warn-bg, #FEF3C7);color:var(--dk-txt-warn, #b45309)}
.dexit__i svg{width:17px;height:17px}
.dexit__btns{display:grid;grid-template-columns:1fr 1fr;gap:10px}
@media (max-width:480px){.dexit__btns{grid-template-columns:1fr}}

/* ── Floating meeting ─────────────────────────────────────────────── */
/* Cards that are wider than the floating panel are centred on the viewport
   instead of being clipped inside it — the extension dialog in particular,
   which is where the client picks minutes and sees the price. */
.mtg__ext--over,.mtg__pause--over{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:240;
  width:min(420px,calc(100vw - 32px));max-width:none;max-height:min(80vh,560px);overflow-y:auto}
.mtg__ext--over::before,.mtg__pause--over::before{content:"";position:fixed;inset:0;z-index:-1;background:rgba(3,16,43,.5);backdrop-filter:blur(3px)}
.mtg__ext--over .mtg__ext-mins{gap:8px}
.mtg__ext--over .mtg__ext-mins button{padding:10px 14px;font-size:.92rem}
/* Three sizes, so the bar never has to guess which control does what. */
.mtg__ftools .mtg__tool{width:30px;height:30px}
.mtg--fmin .mtg__grip{display:none}

@media (prefers-reduced-motion:reduce){
  .docbuild__exit{transition:none}
  .docbuild__exit:active{transform:none}
}

/* ── wp-chatfit: the chat inside a narrow panel ───────────────────────
   Measured against the advocate's document workspace, where SecureChat sits
   in the right column. Four separate defects, all of them only visible once
   the column is narrow:

   1. The per-message wrapper div stopped .sbub from being the flex child of
      .schat__body, so align-self never applied and every bubble came out at
      exactly max-width:78% of the column whatever it held. Fixed in
      SecureChat.tsx (Fragment); nothing to do here.
   2. .deditor__chat bleeds to -16px while the panel's padding is 14px
      (globals.css:5590 overrides the 16px at :4368), so the chat sat 2px
      outside the panel on each side and .sbub__av — which hangs at the very
      left — was the part that got clipped.
   3. A file card's name was `white-space:nowrap` + ellipsis, which turns
      "Screenshot 2026-09-15 110012.png" into "Screenshot 202…" the moment the
      column is narrow. A filename is what tells you which file it is.
   4. <audio> has an intrinsic minimum width (~200px in Chromium) and does not
      shrink below it, so a voice note forced the bubble wider than the column. */
.deditor__chat{margin:0 -14px -14px}
/* The file card wraps its name over two lines rather than cutting it off, and
   nothing inside it can push the bubble wider than the column. */
.sattach--file{max-width:100%}
.sattach__t{min-width:0}
.sattach__t b{white-space:normal;text-overflow:clip;overflow-wrap:anywhere;line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.sattach__t small{overflow-wrap:anywhere}
.sattach__i{flex:none}
/* min-width:0 lets the flex item be narrower than its content's intrinsic
   size, which is what allows the shrink at all. */
.schat--compact .sattach--voice audio{max-width:100%;min-width:0}
.sattach--voice{min-width:0;max-width:100%}
.sattach--voice audio{min-width:0}
/* The bubble and everything in it stay inside the column. */
.sbub__wrap{max-width:100%}
.sbub__c{max-width:100%;overflow-wrap:anywhere}
.sbub__blocked,.sbub__meta{max-width:100%}
/* In a narrow panel the avatar is 38px of the column (30px + the 8px gap)
   spent on an icon that says nothing the alignment does not. Dropped there,
   kept at full width. */
.schat--compact .sbub__av{display:none}
.schat--compact .sbub{max-width:100%;gap:0}
.schat--compact .sbub__c{padding:9px 12px;font-size:.88rem}
.schat--compact .schat__body{padding:12px 12px 14px}
@media (max-width:420px){
  .sbub{max-width:92%}
}

/* ── wp-dresize: the chat panel's draggable wall ──────────────────────
   The right column was a fixed 360px track, which is what squeezed the
   conversation. The wall between the editor and the chat is now a real
   separator: drag it, or use the keyboard on it (arrows move, Shift+arrow
   moves faster, Home/End snap to the bounds, Enter toggles wide/standard).
   The grip is there so the affordance is visible rather than something you
   have to discover by hovering a 1px line. */
.deditor__sizer{position:absolute;top:0;bottom:0;right:var(--deditor-rw);width:14px;margin-right:-7px;z-index:3;
  cursor:col-resize;touch-action:none;display:flex;align-items:center;justify-content:center;background:transparent;
  transition:right .2s,background .15s}
.deditor__body--sizing .deditor__sizer{transition:background .15s}
.deditor__sizer::before{content:"";position:absolute;top:0;bottom:0;left:50%;width:1px;margin-left:-.5px;background:var(--line);transition:background .15s,width .15s}
.deditor__sizer:hover::before,.deditor__sizer:focus-visible::before,.deditor__body--sizing .deditor__sizer::before{background:var(--b400);width:2px}
.deditor__sizer:focus-visible{outline:none}
.deditor__sizerGrip{position:relative;width:8px;height:44px;border-radius:var(--pill);background:var(--dk-surface, #fff);
  box-shadow:0 0 0 1px var(--line),var(--s1);display:flex;align-items:center;justify-content:center;transition:background .15s,box-shadow .15s,width .15s}
.deditor__sizerGrip::after{content:"";width:2px;height:16px;border-radius:2px;background:var(--gray2);box-shadow:3px 0 0 var(--gray2),-3px 0 0 var(--gray2);opacity:.55;transition:opacity .15s}
.deditor__sizer:hover .deditor__sizerGrip,.deditor__sizer:focus-visible .deditor__sizerGrip,.deditor__body--sizing .deditor__sizerGrip{background:var(--b600);box-shadow:0 0 0 1px var(--b600),var(--sblue)}
.deditor__sizer:hover .deditor__sizerGrip::after,.deditor__sizer:focus-visible .deditor__sizerGrip::after,.deditor__body--sizing .deditor__sizerGrip::after{background:#fff;box-shadow:3px 0 0 #fff,-3px 0 0 #fff;opacity:1}
/* Below the desktop breakpoint the panels are fixed overlays with their own
   width, so there is no track to drag. */
@media (max-width:1100px){
  .deditor__sizer{display:none}
}
@media (prefers-reduced-motion:reduce){
  .deditor__sizer,.deditor__sizer::before,.deditor__sizerGrip{transition:none}
}

/* ── wp-dfws: the client's document builder, in the advocate editor's frame ─
   ServiceDocumentPage → DocFill's workspace mode (DocChromeContext). It is the
   same .deditor the advocate edits in — top bar with the document's name, a
   status badge and the actions over the right panel; white side panels with
   their collapse tabs and drag wall; the document on the editor's grey in the
   middle — so only what differs is written here: the left panel holds the
   questions (and is the one with the wall), the middle holds the real page
   (DocPaper's `page` mode) where the advocate has OnlyOffice, and on a phone
   the form is a tab rather than a drawer, because it is what you fill in. */
/* width:100% because .docbuild centres itself with auto margins, which in the
   portal's grid shrink-wraps it to its content — on a phone that let the
   workspace grow past the screen instead of fitting it. */
.docbuild--full:has(.deditor--fill){padding:0;overflow:hidden;width:100%;min-width:0}
.docbuild--full:has(.deditor--fill)>.docbuild__top{display:none}
.docbuild--full .cform--doc:has(>.deditor--fill){position:relative}
.cform--doc>.deditor--fill{flex:1;min-height:0;height:auto}
/* DocumentRequestPanel's own error line, beneath the workspace: a toast,
   placed where the advocate's .deditor__toasts are. */
.cform--doc:has(>.deditor--fill)>.anote{position:absolute;top:64px;left:50%;transform:translateX(-50%);z-index:12;max-width:min(520px,92vw);box-shadow:var(--s2)}

.deditor--fill .deditor__left{padding:0;gap:0;overflow:hidden}
.deditor--fill .docfill__h{flex:none;padding:16px 22px 14px 18px;border-bottom:1px solid var(--line)}
.deditor--fill .docfill__list{flex:1 1 auto;padding:16px 22px 20px 16px}
.deditor--fill .docfill__f{position:static;flex:none;padding:12px 18px 14px;background:var(--dk-surface, #fff)}
.deditor--fill .docfill__f:has(.docfill__st:empty){gap:6px}
.deditor--fill .dfws__submit{display:none}
.deditor--fill .deditor__actions a.deditor__act{text-decoration:none}
.deditor--fill .dpane>.deditor__act,.deditor--fill .dpane>a.deditor__act{justify-content:center}
/* "Advokatdan yordam" — the constructor's own loud action, red and softly
   pulsing (docpaperAskPulse, shared with the two-pane .docpaper__ask), so a
   client stuck on the form sees the way out. Sent, it settles into the quiet
   green of a done thing. Scoped to .deditor--fill: the advocate editor's
   .deditor__act buttons are untouched. */
.deditor--fill .deditor__act--help{background:#E5484D;border-color:#E5484D;color:#fff;animation:docpaperAskPulse 2.4s ease-in-out infinite}
.deditor--fill .deditor__act--help:hover:not(:disabled){background:#D63B40;border-color:#D63B40}
.deditor--fill .deditor__act--help:focus-visible{outline:2px solid #E5484D;outline-offset:2px}
.deditor--fill .deditor__act--help:disabled{animation:none}
.deditor--fill .deditor__act--helpSent,.deditor--fill .deditor__act--helpSent:disabled{opacity:1;background:var(--dk-tint-ok, #E1F6EE);border-color:transparent;color:var(--dk-txt-ok, #0a7d55)}
@media (prefers-reduced-motion:reduce){.deditor--fill .deditor__act--help{animation:none}}

/* The wall on the left panel: the advocate's own grip, mirrored. */
.deditor__sizer--left{right:auto;left:var(--deditor-lw);margin-right:0;margin-left:-7px;transition:left .2s,background .15s}

/* The page, on the editor's grey. DocPaper's toolbar becomes the strip
   OnlyOffice has along its top edge. */
.deditor--fill .deditor__main{display:flex;flex-direction:column}
.deditor--fill .docpaper{gap:0}
.deditor--fill .docpaper__top{flex:none;min-height:46px;padding:7px 14px;background:var(--dk-surface, #fff);border-bottom:1px solid var(--line)}
.deditor--fill .docpaper__srcerr{margin:6px 14px 0}
.deditor--fill .docpaper__scroll{border-radius:0;box-shadow:none;background:transparent;padding:clamp(14px,2.2vw,32px)}

/* Right panel: the sections, each with how far along it is. */
.dfws__secs{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px}
.dfws__sec{width:100%;display:grid;grid-template-columns:28px minmax(0,1fr);align-items:center;gap:6px 10px;padding:10px 12px;border-radius:14px;border:1px solid var(--line);background:var(--dk-surface-2, #F8FAFD);font:inherit;text-align:left;color:var(--ink);cursor:pointer;transition:border-color .15s,background .15s}
.dfws__sec:hover{border-color:var(--b300);background:var(--dk-surface, #fff)}
.dfws__sec:focus-visible{outline:2px solid var(--b400);outline-offset:2px}
.dfws__secn{grid-row:span 2;width:28px;height:28px;border-radius:9px;display:grid;place-items:center;background:var(--dk-surface, #fff);border:1px solid var(--line);font-size:.76rem;font-weight:800;color:var(--gray)}
.dfws__secn svg{width:14px;height:14px;stroke-width:3}
.dfws__sec.done .dfws__secn{background:var(--dk-tint-ok, #E1F6EE);color:var(--dk-txt-ok, #0a7d55);border-color:transparent}
.dfws__sect{display:flex;align-items:baseline;justify-content:space-between;gap:8px;min-width:0}
.dfws__sect b{min-width:0;font-size:.84rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dfws__sect small{flex:none;font-size:.72rem;font-weight:700;color:var(--gray2);font-variant-numeric:tabular-nums}
.dfws__secbar{height:4px;border-radius:var(--pill);background:var(--line);overflow:hidden}
.dfws__secbar i{display:block;height:100%;border-radius:inherit;background:var(--grad);transition:width .3s}
.dfws__sec.done .dfws__secbar i{background:var(--ok)}

/* The form/page switcher only exists where the two cannot sit side by side. */
.deditor--fill .dfws__tabs{display:none}
@media (max-width:1100px){
  .deditor--fill .dfws__tabs{display:flex;flex:none;margin:10px 12px 0}
  .deditor--fill .deditor__body{grid-template-columns:minmax(0,1fr)}
  .deditor--fill .deditor__left,.deditor--fill .deditor__left.on{position:relative;top:auto;bottom:auto;left:auto;z-index:auto;width:auto;box-shadow:none;border-right:0;display:none;margin-top:10px}
  .deditor--fill .deditor__left.is-tab{display:flex}
  .deditor--fill .deditor__main{display:none}
  .deditor--fill .deditor__main.is-tab{display:flex;margin-top:10px}
  .deditor--fill .deditor__left .deditor__panelToggle,.deditor--fill .deditor__toggle--left,.deditor--fill .deditor__sizer--left{display:none}
  .deditor--fill .dfws__submit{display:inline-flex}
  .deditor--fill .deditor__actions .deditor__act--primary{display:none}
  .deditor--fill .docfill__h,.deditor--fill .docfill__list{padding-right:16px}
}
@media (max-width:640px){
  .deditor--fill .docfill__lead{display:none}
  .deditor--fill .docfill__h{padding:12px 14px 10px}
  .deditor--fill .docfill__list{padding:12px 12px 16px}
}
@media (prefers-reduced-motion:reduce){
  .deditor__sizer--left,.dfws__secbar i{transition:none}
}

/* ── wp-chatimg: photos in a secure chat ──────────────────────────────
   A picture sent into the chat used to render as a file card whose only
   action was to download it. It shows as itself now, and clicking it opens a
   full-size viewer over the page rather than saving a file nobody asked for;
   downloading is still there, as the small button under the thumbnail. */
.sattach--img{display:flex;flex-direction:column;gap:5px;min-width:0;max-width:100%}
.sattach__thumb{display:block;position:relative;padding:0;border:0;background:none;cursor:zoom-in;border-radius:12px;overflow:hidden;line-height:0;
  box-shadow:0 0 0 1px var(--line)}
.sattach__thumb img{display:block;width:100%;height:auto;max-height:320px;object-fit:cover;border-radius:12px}
.sattach__zoom{position:absolute;right:8px;bottom:8px;width:26px;height:26px;border-radius:9px;display:grid;place-items:center;
  background:rgba(3,16,43,.55);color:#fff;opacity:0;transition:opacity .16s}
.sattach__zoom svg{width:14px;height:14px}
.sattach__thumb:hover .sattach__zoom,.sattach__thumb:focus-visible .sattach__zoom{opacity:1}
/* A square while the bytes are still coming, so the list does not jump when
   the picture lands. */
.sattach__ph{display:grid;place-items:center;min-height:120px;border-radius:12px;background:var(--dk-surface-2, #F1F5FB);
  box-shadow:inset 0 0 0 1px var(--line);font-size:.78rem;color:var(--gray);padding:10px;text-align:center}
.sattach__cap{display:flex;align-items:center;gap:8px;min-width:0}
.sattach__cap small{flex:1;min-width:0;font-size:.74rem;color:var(--gray);overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:1;line-clamp:1;-webkit-box-orient:vertical;overflow:hidden}
.sattach__dlbtn{flex:none;width:24px;height:24px;border-radius:8px;border:0;cursor:pointer;display:grid;place-items:center;
  background:var(--dk-surface-2, #EEF4FD);color:var(--gray);transition:background .15s,color .15s}
.sattach__dlbtn svg{width:13px;height:13px}
.sattach__dlbtn:hover:not(:disabled){background:var(--b100);color:var(--dk-acc, var(--b600))}
.sattach__dlbtn:disabled{opacity:.5;cursor:default}
.sbub--me .sattach__cap small{color:rgba(255,255,255,.8)}
.sbub--me .sattach__dlbtn{background:rgba(255,255,255,.18);color:#fff}
.sbub--me .sattach__dlbtn:hover:not(:disabled){background:rgba(255,255,255,.3)}
.sbub--me .sattach__ph{background:rgba(255,255,255,.14);box-shadow:inset 0 0 0 1px rgba(255,255,255,.22);color:rgba(255,255,255,.85)}

/* The viewer. Portaled to <body>, so the scrolling message list, the 360px
   panel and the modal above it can none of them clip it. */
.slight{position:fixed;inset:0;z-index:300;display:grid;place-items:center;padding:56px 16px 16px;
  background:rgba(3,10,26,.88);backdrop-filter:blur(6px);animation:fade .18s ease both;cursor:zoom-out}
.slight__img{max-width:100%;max-height:100%;object-fit:contain;border-radius:8px;box-shadow:var(--s3);cursor:default;
  animation:pop .22s cubic-bezier(.2,.8,.3,1) both}
.slight__bar{position:fixed;top:0;left:0;right:0;height:52px;display:flex;align-items:center;gap:10px;padding:0 14px;color:#fff}
