.mk-svc__end{flex:none;width:150px;display:flex;flex-direction:column;align-items:flex-end;gap:8px;padding-left:18px;border-left:2px dashed var(--line)}
.mk-svc__end b{font-family:var(--fd);font-size:1.05rem;letter-spacing:-.02em;color:var(--ink);white-space:nowrap}
.mk-tags{display:flex;flex-wrap:wrap;gap:8px}
.mk-tag{padding:6px 12px;border-radius:var(--pill);background:var(--dk-tint-blue, #EEF5FF);color:var(--dk-acc-strong, var(--b700));font-size:.82rem;font-weight:600}
.mk-facts{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;margin:18px 0 0}
.mk-facts div{padding:12px 14px;border-radius:14px;background:var(--dk-surface-2, #F7FAFE)}
.mk-facts dt{font-size:.72rem;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--gray2)}
.mk-facts dd{margin:4px 0 0;color:var(--ink);font-weight:600;word-break:break-word}
.mk-reviews{list-style:none;margin:12px 0 0;padding:0;display:flex;flex-direction:column;gap:12px}
.mk-review{padding:14px 16px;border-radius:16px;background:var(--dk-surface-2, #F7FAFE)}
.mk-review--ghost{height:90px;margin-top:12px;background:linear-gradient(90deg,var(--dk-surface-2, #F2F6FC) 25%,var(--dk-surface, #fff) 50%,var(--dk-surface-2, #F2F6FC) 75%);background-size:200% 100%;animation:mk-shimmer 1.4s linear infinite}
.mk-review__h{display:flex;flex-wrap:wrap;align-items:center;gap:10px}
.mk-review__h b{color:var(--ink)}
.mk-review__h time{margin-left:auto;font-size:.78rem;color:var(--gray2)}
.mk-review p{margin:8px 0 0;color:var(--ink);line-height:1.55}
.mk-review blockquote{margin:10px 0 0;padding:10px 12px;border-left:3px solid var(--b400);border-radius:0 10px 10px 0;background:var(--dk-surface, #fff);color:var(--gray);font-size:.88rem}
.mk-review blockquote small{display:block;font-weight:700;color:var(--ink);margin-bottom:2px}
.mk-stars{display:inline-flex;gap:2px}
.mk-stars svg{width:15px;height:15px;fill:var(--line)}
.mk-stars svg.on{fill:var(--mk-gold)}
.mk-side{position:sticky;top:90px;display:flex;flex-direction:column;gap:14px}
.mk-side__card{display:flex;flex-direction:column;gap:12px;padding:20px;border-radius:var(--rl);background:var(--dk-surface, #fff);box-shadow:inset 0 0 0 1.5px var(--line),var(--s2)}
.mk-side__card>small{font-size:.8rem;font-weight:700;color:var(--gray);line-height:1.35}
.mk-side__price{font-family:var(--fd);font-size:1.9rem;letter-spacing:-.035em;color:var(--ink);line-height:1.1}
.mk-side__price span{font-size:1rem;color:var(--gray);font-weight:600}
.mk-side__eta{display:inline-flex;align-items:center;gap:6px;font-size:.84rem;color:var(--gray)}
.mk-side__eta svg{width:15px;height:15px}
.mk-side__block{display:flex;gap:8px;align-items:flex-start;margin:0;padding:10px 12px;border-radius:12px;background:var(--dk-tint-warn, #FFF6E5);color:var(--dk-txt-warn, #8A5300);font-size:.84rem;font-weight:600}
.mk-side__block svg{width:16px;height:16px;flex:none;margin-top:1px}
.mk-safe{padding:16px 18px;border-radius:var(--rl);background:var(--dk-tint-ok, #EAF8F2);color:var(--ink)}
.mk-safe b{display:flex;align-items:center;gap:8px;font-family:var(--fd);color:var(--dk-txt-ok, #0B7A55)}
.mk-safe b svg{width:18px;height:18px}
.mk-safe ul{margin:10px 0 0;padding:0 0 0 18px;display:flex;flex-direction:column;gap:6px;font-size:.86rem;color:var(--gray)}

.mk-buy{display:flex;flex-direction:column;gap:16px}
.mk-steps{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.mk-steps li{position:relative;display:flex;flex-direction:column;align-items:center;gap:6px;font-size:.74rem;font-weight:700;color:var(--gray2);text-align:center}
.mk-steps li::before{content:"";position:absolute;top:14px;left:calc(-50% + 18px);right:calc(50% + 18px);height:2px;background:var(--line)}
.mk-steps li:first-child::before{display:none}
.mk-steps li::after{content:"";position:absolute;top:14px;left:calc(-50% + 18px);right:calc(50% + 18px);height:2px;border-radius:2px;background:var(--grad);transform:scaleX(0);transform-origin:left center;transition:transform .6s cubic-bezier(.2,.8,.2,1)}
.mk-steps li:first-child::after{display:none}
.mk-steps li.is-done::after,.mk-steps li.is-now::after,.mk-steps li.is-fail::after{transform:scaleX(1)}
.mk-steps li span{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--dk-surface-2, #EEF3FB);color:var(--gray);font-size:.8rem;position:relative;z-index:1;transition:color .3s,box-shadow .3s}
.mk-steps li span svg{width:15px;height:15px}
.mk-steps li.is-done{color:var(--dk-txt-ok, var(--ok))}
.mk-steps li.is-done span{background:var(--ok);color:#fff}
.mk-steps li.is-now{color:var(--ink)}
.mk-steps li.is-now span{background:var(--grad);color:#fff;animation:mk-pulse 1.6s infinite}
.mk-buy__ticket{position:relative;display:flex;gap:16px;justify-content:space-between;align-items:stretch;padding:16px 18px;border-radius:18px;background:var(--grad-dark);color:#fff;overflow:hidden}
.mk-buy__ticket::before,.mk-buy__ticket::after{content:"";position:absolute;right:124px;width:18px;height:18px;border-radius:50%;background:var(--dk-surface, #fff)}
.mk-buy__ticket::before{top:-9px}
.mk-buy__ticket::after{bottom:-9px}
.mk-buy__ticket>div:first-child{display:flex;flex-direction:column;gap:3px;min-width:0}
.mk-buy__ticket small{font-size:.7rem;letter-spacing:.06em;text-transform:uppercase;color:rgba(255,255,255,.6);font-weight:700}
.mk-buy__ticket b{font-family:var(--fd);font-size:1.02rem}
.mk-buy__ticket p{margin:0;color:rgba(255,255,255,.85);font-size:.9rem;line-height:1.35}
.mk-buy__eta{display:inline-flex;align-items:center;gap:5px;margin-top:4px;font-size:.78rem;color:var(--cy)}
.mk-buy__eta svg{width:14px;height:14px}
.mk-buy__sum{flex:none;width:112px;display:flex;flex-direction:column;align-items:flex-end;justify-content:center;padding-left:16px;border-left:2px dashed rgba(255,255,255,.28)}
.mk-buy__sum b{font-size:1.25rem;letter-spacing:-.02em}
.mk-buy__sum span{font-size:.78rem;color:rgba(255,255,255,.7)}
.mk-buy__form{display:flex;flex-direction:column;gap:14px}
.mk-buy__ch{border:0;margin:0;padding:0;min-width:0}
.mk-buy__ch legend{padding:0;margin-bottom:8px;font-size:.78rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--gray2)}
.mk-seg{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.mk-seg__b{display:flex;flex-direction:column;align-items:center;gap:6px;padding:12px 6px;border:0;border-radius:14px;background:var(--dk-surface-2, #F2F6FC);color:var(--gray);font-weight:700;font-size:.76rem;cursor:pointer;transition:background .2s,color .2s,box-shadow .2s,transform .15s;text-align:center;line-height:1.2}
.mk-seg__b svg{width:20px;height:20px}
.mk-seg__b:hover{color:var(--ink)}
.mk-seg__b:active{transform:scale(.97)}
.mk-seg__b[aria-pressed=true]{background:var(--dk-tint-blue, #EAF2FF);color:var(--dk-acc-strong, var(--b700));box-shadow:inset 0 0 0 2px var(--b500)}
.mk-in{position:relative;display:flex;flex-direction:column;gap:6px}
.mk-in>span{font-size:.78rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--gray2)}
.mk-in textarea,.mk-in input{width:100%;border:0;border-radius:14px;padding:12px 14px;background:var(--dk-surface-2, #F7FAFE);font-size:.95rem;line-height:1.5;color:var(--ink);box-shadow:inset 0 0 0 1.5px transparent;transition:box-shadow .2s,background .2s;resize:vertical}
.mk-in textarea:focus,.mk-in input:focus{outline:none;box-shadow:inset 0 0 0 1.5px var(--b400);background:var(--dk-surface, #fff)}
.mk-in em{position:absolute;right:10px;bottom:8px;font-style:normal;font-size:.7rem;color:var(--gray2);pointer-events:none}
.mk-quick{display:flex;flex-wrap:wrap;gap:6px;margin-top:-6px}
.mk-buy__note{margin:0;font-size:.8rem;color:var(--gray)}
.mk-buy__acts{display:flex;flex-wrap:wrap;gap:10px;justify-content:center}
.mk-receipt{display:flex;flex-direction:column;align-items:center;gap:10px;padding:18px 12px 4px;text-align:center}
.mk-receipt__t{font-family:var(--fd);font-size:1.25rem;line-height:1.25;color:var(--ink)}
.mk-receipt p{margin:0;color:var(--gray);font-size:.9rem;max-width:420px}
.mk-receipt__stamp{display:grid;place-items:center;width:64px;height:64px;border-radius:50%;background:var(--ok);color:#fff;box-shadow:0 0 0 8px var(--dk-tint-ok, #E1F6EE);animation:mk-stamp .6s cubic-bezier(.2,.8,.3,1) both}
.mk-receipt__stamp svg{width:30px;height:30px}
.mk-receipt--warn .mk-receipt__t{font-size:1.02rem;max-width:400px}
.mk-pending{display:inline-flex;align-items:center;gap:8px;padding:6px 12px;border-radius:var(--pill);background:var(--dk-tint-warn, #FFF4DE);color:var(--dk-txt-warn, #8A5300);font-size:.82rem;font-weight:700}
.mk-pending i{flex:none;width:8px;height:8px;border-radius:50%;background:var(--mk-gold);animation:mk-pulse 1.4s infinite}
.mk-pending--line{display:flex;border-radius:12px;margin:0;line-height:1.4}

.mk-orders__head{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:12px}
.mk-orders__t{margin:0;font-family:var(--fd);font-size:clamp(1.4rem,2.4vw,1.9rem);letter-spacing:-.03em;color:var(--ink)}
.mk-orders__l{margin:4px 0 0;color:var(--gray);max-width:620px}
.mk-spin{animation:mk-spin .9s linear infinite}
.mk-flash{display:flex;align-items:center;gap:8px;padding:10px 14px;border-radius:12px;background:var(--dk-tint-ok, #E1F6EE);color:var(--dk-txt-ok, #0B7A55);font-weight:700;font-size:.88rem;animation:mk-rise .3s both}
.mk-flash svg{width:16px;height:16px}
.mk-olist{display:flex;flex-direction:column;gap:14px;transition:opacity .2s}
.mk-olist.is-busy{opacity:.6}
.mk-order{--mk-rail:var(--b500);position:relative;display:flex;border-radius:20px;background:var(--dk-surface, #fff);box-shadow:inset 0 0 0 1px var(--line),var(--s1);overflow:hidden;animation:mk-rise .4s both}
.mk-order--pending{--mk-rail:var(--mk-gold)}
.mk-order--completed{--mk-rail:var(--ok)}
.mk-order--cancelled{--mk-rail:var(--gray2)}
.mk-order--ghost{min-height:170px;background:linear-gradient(90deg,var(--dk-surface-2, #F2F6FC) 25%,var(--dk-surface, #fff) 50%,var(--dk-surface-2, #F2F6FC) 75%);background-size:200% 100%;animation:mk-shimmer 1.4s linear infinite}
.mk-order__rail{flex:none;width:6px;background:var(--mk-rail)}
.mk-order__main{flex:1;min-width:0;display:flex;flex-direction:column;gap:12px;padding:16px 18px}
.mk-order__top{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px}
.mk-order__id{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.mk-order__price{font-family:var(--fd);font-size:1.15rem;letter-spacing:-.02em;color:var(--ink)}
.mk-order__price small{font-size:.78rem;color:var(--gray);font-weight:600}
.mk-order__svc{margin:0;font-family:var(--fd);font-size:1.06rem;letter-spacing:-.015em;color:var(--ink);line-height:1.3}
.mk-stage{display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:var(--pill);font-size:.74rem;font-weight:800;background:var(--dk-tint-blue, #E6F0FF);color:var(--dk-acc-strong, var(--b700))}
.mk-stage i{width:7px;height:7px;border-radius:50%;background:var(--mk-gold);animation:mk-pulse 1.4s infinite}
.mk-stage--pending{background:var(--dk-tint-warn, #FFF4DE);color:var(--dk-txt-warn, #8A5300)}
.mk-stage--completed{background:var(--dk-tint-ok, #E1F6EE);color:var(--dk-txt-ok, #0B7A55)}
.mk-stage--cancelled{background:var(--dk-surface-2, #EEF1F5);color:var(--gray)}
.mk-track{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,1fr)}
.mk-track li{position:relative;display:flex;flex-direction:column;gap:6px;font-size:.72rem;font-weight:700;color:var(--gray2)}
.mk-track li span{position:relative;height:6px;border-radius:var(--pill);margin-right:4px;background:var(--dk-surface-2, #E9EEF6);overflow:hidden}
.mk-track li.is-done span{background:var(--grad)}
.mk-track li.is-now span::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent,var(--b400),transparent);background-size:200% 100%;animation:mk-shimmer 1.6s linear infinite}
.mk-track li.is-done,.mk-track li.is-now{color:var(--ink)}
.mk-order--pending .mk-track li.is-now span::after{background:linear-gradient(90deg,transparent,var(--mk-gold),transparent);background-size:200% 100%}
.mk-order__facts{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:8px 16px;margin:0}
.mk-order__facts div{min-width:0}
.mk-order__facts dt{font-size:.7rem;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--gray2)}
.mk-order__facts dd{margin:3px 0 0;display:flex;align-items:center;gap:6px;color:var(--ink);font-weight:600;font-size:.9rem;word-break:break-word}
.mk-order__facts dd svg{width:15px;height:15px;color:var(--gray);flex:none}
.mk-order__facts a{color:var(--dk-acc, var(--b600))}
.mk-muted{color:var(--gray);font-weight:500;font-size:.84rem}
.mk-order__note{margin:0;padding:10px 12px;border-radius:12px;background:var(--dk-surface-2, #F7FAFE);color:var(--ink);font-size:.9rem;line-height:1.5;white-space:pre-line}
.mk-order__note small{display:block;font-size:.7rem;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--gray2);margin-bottom:2px}
.mk-order__acts{display:flex;flex-wrap:wrap;gap:8px}
.mk-callgrp{display:inline-flex;gap:6px}
.btn.mk-danger{color:var(--dk-txt-err, #C0392B)}
.btn.mk-danger:hover{box-shadow:inset 0 0 0 1.5px var(--dk-bd-err, #F5B7B1);color:var(--dk-txt-err, #C0392B)}
.mk-act{display:flex;flex-direction:column;gap:14px}
.mk-act__head{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.mk-act__head b{color:var(--ink)}
.mk-act>p{margin:0;color:var(--gray)}

.mk-toasts{position:fixed;right:max(16px,env(safe-area-inset-right));bottom:max(16px,env(safe-area-inset-bottom));z-index:1200;display:flex;flex-direction:column;gap:10px;width:min(380px,calc(100vw - 32px))}
.mk-toast{display:flex;align-items:flex-start;gap:12px;padding:14px 14px 14px 16px;border-radius:18px;background:var(--dk-glass, rgba(255,255,255,.94));backdrop-filter:blur(14px);box-shadow:inset 0 0 0 1px var(--line),var(--s3);animation:mk-toast .35s cubic-bezier(.2,.8,.3,1) both}
.mk-toast__ic{flex:none;display:grid;place-items:center;width:36px;height:36px;border-radius:12px;background:var(--grad);color:#fff}
.mk-toast__ic svg{width:18px;height:18px}
.mk-toast--paid .mk-toast__ic{background:linear-gradient(135deg,#00A870,#3DDC97)}
.mk-toast--rejected .mk-toast__ic{background:linear-gradient(135deg,#8A99AC,#5C6E85)}
.mk-toast__b{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}
.mk-toast__b b{color:var(--ink);font-family:var(--fd)}
.mk-toast__b span{color:var(--gray);font-size:.86rem;line-height:1.4}
.mk-toast__go{align-self:flex-start;margin-top:4px;font-weight:700;font-size:.84rem;color:var(--dk-acc, var(--b600))}
.mk-toast__x{flex:none;border:0;background:none;padding:4px;color:var(--gray);cursor:pointer;border-radius:8px}
.mk-toast__x svg{width:16px;height:16px}

@media (max-width:1100px){
  .mk-prof__body{grid-template-columns:minmax(0,1fr)}
  .mk-side{position:static}
}
@media (max-width:900px){
  .mk-ftoggle{display:inline-flex}
  .mk-filters{display:none}
  .mk-filters.is-open{display:grid;animation:mk-rise .25s both}
}
@media (max-width:560px){
  .mk-seg{grid-template-columns:repeat(2,1fr)}
  .mk-svc{flex-direction:column;align-items:stretch}
  .mk-svc::before,.mk-svc::after{display:none}
  .mk-svc__end{width:auto;flex-direction:row;align-items:center;justify-content:space-between;padding:12px 0 0;border-left:0;border-top:2px dashed var(--line)}
  .mk-buy__ticket{flex-direction:column}
  .mk-buy__ticket::before,.mk-buy__ticket::after{display:none}
  .mk-buy__sum{width:auto;align-items:flex-start;padding:12px 0 0;border-left:0;border-top:2px dashed rgba(255,255,255,.28)}
  .mk-track li{font-size:.64rem}
  .mk-card__head{padding-right:0}
  .mk-card__ad{position:static;align-self:flex-start;order:-1}
  .mk-hero__stats>div{min-width:0;flex:1}
}
@media (prefers-reduced-motion:reduce){
  .mk-hero__glow,.mk-card,.mk-order,.mk-toast,.mk-receipt__stamp{animation:none}
}
.mk .btn:disabled{opacity:.5;cursor:not-allowed;filter:saturate(.6);box-shadow:none}
.mk .btn:disabled::before{display:none}
@keyframes mk-float{0%,100%{transform:var(--mk-t) translateY(0)}50%{transform:var(--mk-t) translateY(-10px)}}
@media (max-width:560px){.mk-hero__stats{gap:8px}.mk-hero__stats>div{padding:9px 10px}.mk-hero__stats b{font-size:1.02rem}.mk-hero__stats span{font-size:.7rem}}
.mk-eta{display:inline-flex;align-items:center;gap:4px;white-space:nowrap}

/* ═══════════════ WORK FILTER BAR (wfb-) ═══════════════ */
.uf.wfb{margin:0 0 16px}
@media (min-width:901px){.wfb--split .uf-card .uf-fld--search{grid-column:1/-1}}
.wfb__empty{display:flex;flex-direction:column;align-items:center;gap:6px;padding-bottom:18px}
.wfb__flow{display:inline-flex;align-self:flex-start;align-items:center;gap:6px;padding:4px 10px;border-radius:var(--pill);font-size:.74rem;font-weight:700;background:var(--dk-tint-blue, #EAF2FF);color:var(--dk-acc-strong, var(--b700))}
.wfb__flow svg{width:13px;height:13px}
.wfb__flow--custom_from_scratch{background:var(--dk-tint-violet, #EFEAFE);color:var(--dk-txt-violet, #5B3CC4)}
.wfb__flow--review_existing_document{background:var(--dk-tint-ok, #E1F6EE);color:var(--dk-txt-ok, #0B7A55)}
.pcase--late{box-shadow:inset 0 0 0 1.5px var(--dk-bd-warn, #F6C667),0 12px 30px -20px rgba(244,182,63,.7)}
.pcase__wait{color:var(--dk-txt-warn, #8A5300);font-weight:700}
.wfb__flow{justify-self:start}
.mkm{--mkm-done:#0ca30c;--mkm-active:#2a78d6;--mkm-pending:#fab219;--mkm-cancel:#d03b3b;--mkm-other:#898781;display:flex;flex-direction:column;gap:16px;min-width:0}
html[data-theme="dark"] .mkm{--mkm-active:#3987e5}
@keyframes mkm-ping{0%{box-shadow:0 0 0 0 rgba(61,220,151,.55)}70%{box-shadow:0 0 0 8px rgba(61,220,151,0)}100%{box-shadow:0 0 0 0 rgba(61,220,151,0)}}
.mkm-sr{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.mkm-tone--done{--mkm-c:var(--mkm-done)}
.mkm-tone--active{--mkm-c:var(--mkm-active)}
.mkm-tone--pending{--mkm-c:var(--mkm-pending)}
.mkm-tone--cancel{--mkm-c:var(--mkm-cancel)}
.mkm-tone--other{--mkm-c:var(--mkm-other)}
.mkm-spin{animation:mk-spin .9s linear infinite}
.mkm-muted{margin:0;color:var(--gray);font-size:.86rem}
.mkm-panel{min-width:0}
.mkm-sep>span{white-space:nowrap}
.mkm-sep>span:not(:last-child)::after{content:"·";margin:0 6px;color:var(--gray2)}

.mkm-hero{position:relative;overflow:hidden;overflow:clip;isolation:isolate;border-radius:var(--rx);background:var(--grad-dark);color:#fff;padding:clamp(20px,3vw,34px) clamp(18px,3vw,36px) 0}
.mkm-hero__glow{position:absolute;inset:-45%;z-index:-2;background:radial-gradient(34% 40% at 24% 30%,rgba(0,207,232,.36),transparent 70%),radial-gradient(30% 36% at 78% 58%,rgba(92,168,255,.32),transparent 70%),radial-gradient(18% 22% at 62% 14%,rgba(61,220,151,.16),transparent 70%);animation:mk-aurora 30s linear infinite;pointer-events:none}
.mkm-hero__grid{position:absolute;inset:0;z-index:-1;background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);background-size:40px 40px;mask-image:radial-gradient(ellipse at 80% 20%,#000 10%,transparent 70%);-webkit-mask-image:radial-gradient(ellipse at 80% 20%,#000 10%,transparent 70%)}
.mkm-hero__top{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:18px 28px}
.mkm-hero__txt{flex:1 1 360px;min-width:0;display:flex;flex-direction:column;gap:10px}
.mkm-hero__eyebrow{display:inline-flex;flex-wrap:wrap;align-items:center;gap:8px;font-size:.72rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.8)}
.mkm-hero__eyebrow em{font-style:normal;font-weight:600;letter-spacing:.01em;text-transform:none;color:rgba(255,255,255,.6)}
.mkm-live{flex:none;width:8px;height:8px;border-radius:50%;background:#3DDC97;animation:mkm-ping 2s infinite}
.mkm-live.is-off{background:#FBC15E;animation:none}
.mkm-hero__t{margin:0;font-family:var(--fd);font-size:clamp(1.5rem,2.8vw,2.2rem);line-height:1.1;letter-spacing:-.03em;font-weight:800}
.mkm-hero__l{margin:0;max-width:600px;color:rgba(255,255,255,.74);font-size:.94rem;line-height:1.5}
.mkm-rev{flex:0 1 auto;min-width:min(100%,270px);max-width:100%;display:flex;flex-direction:column;gap:4px;padding:16px 20px;border-radius:20px;background:rgba(255,255,255,.08);box-shadow:inset 0 0 0 1px rgba(255,255,255,.16);backdrop-filter:blur(10px);transition:opacity .2s}
.mkm-rev.is-busy{opacity:.55}
.mkm-rev__l{font-size:.7rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.72)}
.mkm-rev__v{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px;font-family:var(--fd);font-size:clamp(1.7rem,3.4vw,2.5rem);font-weight:800;letter-spacing:-.035em;line-height:1.05}
.mkm-rev__v small{font-size:.9rem;font-weight:700;letter-spacing:0;color:rgba(255,255,255,.72)}
.mkm-rev__s{font-size:.84rem;font-weight:600;color:rgba(255,255,255,.82)}
.mkm-rev__scope{align-self:flex-start;max-width:100%;margin-top:4px;padding:4px 10px;border-radius:var(--pill);background:rgba(255,255,255,.12);font-size:.74rem;font-weight:700;color:rgba(255,255,255,.88);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mkm-hero__bar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:22px;padding:10px 0 14px;border-top:1px solid rgba(255,255,255,.12)}
.mkm-tabs{display:flex;gap:6px;min-width:0;padding:4px;margin:-4px;overflow-x:auto;scrollbar-width:none}
.mkm-tabs::-webkit-scrollbar{display:none}
.mkm-tab{flex:none;display:inline-flex;align-items:center;gap:8px;border:0;padding:9px 16px;border-radius:var(--pill);background:transparent;color:rgba(255,255,255,.74);font-weight:700;font-size:.9rem;cursor:pointer;transition:background .2s,color .2s}
.mkm-tab:hover{color:#fff;background:rgba(255,255,255,.08)}
.mkm-tab:focus-visible{outline:2px solid #fff;outline-offset:2px}
.mkm-tab[aria-selected=true]{background:var(--dk-surface, #fff);color:var(--dk-acc-strong, var(--b700));box-shadow:0 10px 24px -12px rgba(0,0,0,.55)}
.mkm-tab span{display:inline-grid;place-items:center;min-width:22px;height:22px;padding:0 7px;border-radius:var(--pill);background:rgba(255,255,255,.14);font-size:.74rem;font-variant-numeric:tabular-nums}
.mkm-tab[aria-selected=true] span{background:var(--b100);color:var(--dk-acc-strong, var(--b700))}
.mkm-refresh{flex:none;display:grid;place-items:center;width:38px;height:38px;border:0;border-radius:12px;background:rgba(255,255,255,.1);color:#fff;cursor:pointer;transition:background .2s}
.mkm-refresh:hover{background:rgba(255,255,255,.18)}
.mkm-refresh:focus-visible{outline:2px solid #fff;outline-offset:2px}
.mkm-refresh:disabled{cursor:default}
.mkm-refresh svg{width:17px;height:17px}

.mkm-fnote{margin:0;padding:8px 12px;border-radius:12px;background:var(--dk-surface-2, #F7FAFE);font-size:.8rem;color:var(--gray);line-height:1.45}

.mkm-over{display:flex;flex-direction:column;gap:14px;min-width:0}
.mkm-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;transition:opacity .2s}
.mkm-kpis.is-busy{opacity:.55}
.mkm-kpi{--mkm-k:var(--b500);position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:8px;min-width:0;padding:16px;border:0;border-radius:18px;background:var(--dk-surface, #fff);box-shadow:inset 0 0 0 1px var(--line);text-align:left;font:inherit;color:var(--ink);overflow:hidden;overflow:clip}
.mkm-kpi::before{content:"";position:absolute;left:16px;right:16px;top:0;height:3px;border-radius:0 0 3px 3px;background:var(--mkm-k)}
.mkm-kpi--active{--mkm-k:var(--mkm-active)}
.mkm-kpi--done{--mkm-k:var(--mkm-done)}
.mkm-kpi--pending{--mkm-k:var(--mkm-pending)}
.mkm-kpi--cancel{--mkm-k:var(--mkm-cancel)}
.mkm-kpi--btn{cursor:pointer;transition:box-shadow .2s,transform .2s}
.mkm-kpi--btn:hover{box-shadow:inset 0 0 0 1.5px var(--b300),var(--s2);transform:translateY(-2px)}
.mkm-kpi--btn:focus-visible{outline:2px solid var(--b500);outline-offset:2px}
.mkm-kpi--ghost{min-height:104px;background:linear-gradient(90deg,var(--dk-surface-2, #F2F6FC) 25%,var(--dk-surface, #fff) 50%,var(--dk-surface-2, #F2F6FC) 75%);background-size:200% 100%;animation:mk-shimmer 1.4s linear infinite}
.mkm-kpi--ghost::before{display:none}
.mkm-kpi__h{display:flex;align-items:center;gap:10px;width:100%;min-width:0;padding-right:20px}
.mkm-kpi__i{flex:none;display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:var(--b100);color:var(--dk-acc, var(--b600))}
.mkm-kpi__i svg{width:17px;height:17px}
.mkm-kpi__i--active{background:var(--dk-tint-blue, #E6F0FF);color:var(--dk-acc, #1F63B8)}
.mkm-kpi__i--done{background:var(--dk-tint-ok, #E3F5E3);color:var(--dk-txt-ok, #0A7A0A)}
.mkm-kpi__i--pending{background:var(--dk-tint-warn, #FFF4DE);color:var(--dk-txt-warn, #8A5300)}
.mkm-kpi__i--cancel{background:var(--dk-tint-err, #FDECEC);color:var(--dk-txt-err, #B02E2E)}
.mkm-kpi__l{flex:1;min-width:0;font-size:.82rem;font-weight:600;color:var(--gray);line-height:1.3}
.mkm-kpi__v{font-family:var(--fd);font-size:1.65rem;font-weight:800;letter-spacing:-.03em;line-height:1.05;color:var(--ink)}
.mkm-kpi__s{font-size:.74rem;color:var(--gray2);line-height:1.3}
.mkm-kpi__go{position:absolute;top:16px;right:14px;width:16px;height:16px;color:var(--gray2);opacity:0;transition:opacity .2s,transform .2s}
.mkm-kpi--btn:hover .mkm-kpi__go,.mkm-kpi--btn:focus-visible .mkm-kpi__go{opacity:1;transform:translateX(2px)}

.mkm-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:14px;align-items:start}
.mkm-card{display:flex;flex-direction:column;gap:14px;min-width:0;padding:18px;border-radius:20px;background:var(--dk-surface, #fff);box-shadow:inset 0 0 0 1px var(--line);transition:opacity .2s}
.mkm-card.is-busy{opacity:.55}
.mkm-card__h{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px}
.mkm-card__h b{font-family:var(--fd);font-size:1.02rem;letter-spacing:-.02em;color:var(--ink)}
.mkm-card__h small{display:block;margin-top:2px;font-size:.8rem;font-weight:500;color:var(--gray)}
.mkm-count{display:inline-grid;place-items:center;min-width:32px;height:26px;padding:0 10px;border-radius:var(--pill);background:var(--b100);color:var(--dk-acc-strong, var(--b700));font-size:.8rem;font-weight:800;font-variant-numeric:tabular-nums}
.mkm-link{display:inline-flex;align-items:center;gap:4px;border:0;background:none;padding:6px 0;color:var(--dk-acc, var(--b600));font-weight:700;font-size:.84rem;cursor:pointer;white-space:nowrap}
.mkm-link:hover{text-decoration:underline;text-underline-offset:3px}
.mkm-link svg{width:14px;height:14px}
.mkm-toggle{display:inline-flex;align-items:center;gap:6px;border:0;padding:7px 12px;border-radius:var(--pill);background:var(--dk-surface-2, #F2F6FC);color:var(--gray);font-weight:700;font-size:.8rem;cursor:pointer}
.mkm-toggle:hover{color:var(--ink)}
.mkm-toggle[aria-pressed=true]{background:var(--b600);color:#fff}
.mkm-cardnote{margin:0;padding:8px 12px;border-radius:12px;background:var(--dk-surface-2, #F7FAFE);font-size:.8rem;line-height:1.45;color:var(--gray)}
.mkm-toggle svg{width:14px;height:14px}
.mkm-warn{display:flex;align-items:center;gap:8px;margin:0;padding:10px 14px;border-radius:12px;background:var(--dk-tint-warn, #FFF4DE);color:var(--dk-txt-warn, #8A5300);font-size:.86rem;font-weight:600}
.mkm-warn svg{flex:none;width:16px;height:16px}
.mkm-fail{display:flex;flex-direction:column;align-items:center;gap:6px;padding-bottom:12px}

.mkm-chart{display:flex;flex-direction:column;gap:14px}
.mkm-sbar{position:relative;display:flex;gap:2px;height:22px;margin-top:30px}
.mkm-sbar__seg{min-width:6px;height:100%;background:var(--mkm-c);outline:none;transition:opacity .15s}
.mkm-sbar__seg:first-child{border-radius:4px 0 0 4px}
.mkm-sbar__seg:last-child{border-radius:0 4px 4px 0}
.mkm-sbar__seg:only-child{border-radius:4px}
.mkm-sbar:hover .mkm-sbar__seg:not(:hover){opacity:.5}
.mkm-sbar__seg:focus-visible{box-shadow:0 0 0 2px var(--dk-surface, #fff),0 0 0 4px var(--ink)}
.mkm-tip{position:absolute;left:0;right:0;bottom:calc(100% + 8px);display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:2px 6px;padding:6px 10px;border-radius:10px;background:var(--dk-tip, #0A1526);color:#fff;font-size:.78rem;font-weight:600;text-align:center;pointer-events:none;box-shadow:var(--s2);z-index:2}
.mkm-tip b{font-weight:800}
.mkm-tip::after{content:"";position:absolute;top:100%;left:var(--caret, 50%);transform:translateX(-50%);border:5px solid transparent;border-top-color:var(--dk-tip, #0A1526)}
.mkm-legend{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.mkm-legend li{display:flex;align-items:center;gap:8px;min-width:0;padding:9px 11px;border-radius:12px;background:var(--dk-surface-2, #F7FAFE)}
.mkm-legend li.is-zero{opacity:.6}
.mkm-legend svg{flex:none;width:14px;height:14px;color:var(--gray)}
.mkm-legend span:not(.mkm-legend__sw){flex:1;min-width:0;font-size:.84rem;font-weight:600;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mkm-legend b{font-size:.86rem;color:var(--ink);font-variant-numeric:tabular-nums}
.mkm-legend small{min-width:40px;text-align:right;font-size:.74rem;color:var(--gray);font-variant-numeric:tabular-nums}
.mkm-legend__sw{display:inline-block;flex:none;width:10px;height:10px;margin-right:8px;border-radius:3px;background:var(--mkm-c);vertical-align:-1px}
.mkm-legend li .mkm-legend__sw{margin-right:0}

.mkm-top{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:4px}
.mkm-top__row{width:100%;display:grid;grid-template-columns:20px 36px minmax(0,1fr) auto;grid-template-areas:"rank av who n" "rank av bar bar";align-items:center;gap:8px 12px;padding:10px 8px;border:0;border-radius:14px;background:transparent;text-align:left;font:inherit;color:var(--ink);cursor:pointer;transition:background .15s}
.mkm-top__row:hover{background:var(--dk-surface-2, #F5F8FD)}
.mkm-top__row:focus-visible{outline:2px solid var(--b500);outline-offset:1px}
.mkm-top__rank{grid-area:rank;font-size:.8rem;font-weight:800;color:var(--gray2);text-align:center}
.mkm-top__row>.mkm-av{grid-area:av}
.mkm-av{flex:none;display:grid;place-items:center;width:36px;height:36px;border-radius:12px;background:var(--grad);color:#fff;font-weight:800;font-size:.8rem;letter-spacing:.02em}
.mkm-top__who{grid-area:who;display:flex;flex-direction:column;min-width:0}
.mkm-top__who b{font-size:.9rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mkm-top__who em{font-style:normal;font-size:.75rem;color:var(--gray);line-height:1.35}
.mkm-top__bar{grid-area:bar;height:8px;border-radius:4px;background:var(--dk-surface-2, #EEF2F8);overflow:hidden}
.mkm-top__bar i{display:block;height:100%;border-radius:0 4px 4px 0;background:var(--mkm-active)}
.mkm-top__n{grid-area:n;display:flex;flex-direction:column;align-items:flex-end}
.mkm-top__n b{font-family:var(--fd);font-size:1.1rem;line-height:1}
.mkm-top__n small{font-size:.68rem;color:var(--gray)}

.mkm-latest{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.mkm-latest li+li{border-top:1px solid var(--line)}
.mkm-latest__row{width:100%;display:grid;grid-template-columns:10px 100px minmax(0,1fr) auto auto 140px;align-items:center;gap:12px;padding:12px 8px;border:0;border-radius:12px;background:transparent;text-align:left;font:inherit;color:var(--ink);cursor:pointer;transition:background .15s}
.mkm-latest__row:hover{background:var(--dk-surface-2, #F5F8FD)}
.mkm-latest__row:focus-visible{outline:2px solid var(--b500);outline-offset:1px}
.mkm-dot{width:10px;height:10px;border-radius:50%;background:var(--mkm-c)}
.mkm-wid{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.8rem;font-weight:800;letter-spacing:.02em;color:var(--dk-acc-strong, var(--b700))}
.mkm-latest__svc{display:flex;flex-direction:column;min-width:0}
.mkm-latest__svc b{font-size:.9rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mkm-latest__svc em{font-style:normal;font-size:.76rem;color:var(--gray);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mkm-latest__amt{font-weight:800;font-size:.9rem;white-space:nowrap;font-variant-numeric:tabular-nums}
.mkm-latest__when{font-size:.78rem;color:var(--gray);text-align:right;white-space:nowrap}

.mkm-st{display:inline-flex;align-items:center;gap:5px;padding:4px 10px 4px 8px;border-radius:var(--pill);font-size:.74rem;font-weight:800;white-space:nowrap;background:var(--dk-surface-2, #EEF1F5);color:var(--gray)}
.mkm-st svg{flex:none;width:13px;height:13px}
.mkm-st--done{background:var(--dk-tint-ok, #E3F5E3);color:var(--dk-txt-ok, #0A6B0A)}
.mkm-st--active{background:var(--dk-tint-blue, #E6F0FF);color:var(--dk-acc-strong, #1F5FB0)}
.mkm-st--pending{background:var(--dk-tint-warn, #FFF1D6);color:var(--dk-txt-warn, #875000)}
.mkm-st--cancel{background:var(--dk-tint-err, #FDECEC);color:var(--dk-txt-err, #B02E2E)}
.mkm-pay{display:inline-flex;align-items:center;padding:3px 9px;border-radius:var(--pill);font-size:.7rem;font-weight:700;white-space:nowrap;box-shadow:inset 0 0 0 1px var(--line);color:var(--gray)}
.mkm-pay--done{color:var(--dk-txt-ok, #0A6B0A);box-shadow:inset 0 0 0 1px var(--dk-bd-ok, rgba(12,163,12,.35))}
.mkm-pay--pending{color:var(--dk-txt-warn, #875000);box-shadow:inset 0 0 0 1px var(--dk-bd-warn, rgba(250,178,25,.55))}
.mkm-pay--cancel{color:var(--dk-txt-err, #B02E2E);box-shadow:inset 0 0 0 1px var(--dk-bd-err, rgba(208,59,59,.35))}
.mkm-badges{display:inline-flex;flex-wrap:wrap;align-items:center;gap:5px}

.mkm-tablewrap{overflow-x:auto;margin:0 -4px;padding:0 4px 2px;scrollbar-width:thin}
.mkm-table{width:100%;border-collapse:separate;border-spacing:0;font-size:.88rem}
.mkm-table--orders{min-width:1000px}
.mkm-table--sellers{min-width:1000px}
.mkm-table--sellers th{white-space:normal;line-height:1.3;vertical-align:bottom}
.mkm-table--sellers td{padding:12px 10px}
.mkm-table th{text-align:left;font-size:.66rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--gray2);padding:0 12px 10px;white-space:nowrap}
.mkm-table td{padding:12px;border-top:1px solid var(--line);vertical-align:middle;color:var(--ink)}
.mkm-table td b{display:block;font-weight:700;color:var(--ink)}
.mkm-table td small{display:block;margin-top:3px;font-size:.76rem;color:var(--gray)}
.mkm-table .num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
.mkm-table--mini{font-size:.86rem}
.mkm-table--mini td{padding:10px 12px}
.mkm-tr{cursor:pointer;transition:background .15s}
.mkm-tr:hover td{background:var(--b50)}
.mkm-tr__go{width:28px;color:var(--gray2)}
.mkm-tr__go svg{width:16px;height:16px;min-width:16px}
.mkm-idbtn{border:0;background:none;padding:0;cursor:pointer;text-align:left}
.mkm-idbtn:hover{text-decoration:underline;text-underline-offset:3px}
.mkm-idbtn:focus-visible{outline:2px solid var(--b500);outline-offset:2px;border-radius:4px}
.mkm-clamp{display:-webkit-box!important;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;max-width:300px;line-height:1.35}
.mkm-td--id,.mkm-td--who{white-space:nowrap}
.mkm-td--date{white-space:nowrap;color:var(--gray)!important;font-size:.82rem}
.mkm-seller{display:flex;align-items:center;gap:10px;min-width:180px}
.mkm-seller>span:last-child{display:flex;flex-direction:column;align-items:flex-start;min-width:0}
.mkm-seller__name{font:inherit;font-size:.9rem;font-weight:700;color:var(--ink)}
.mkm-acc{align-self:flex-start;margin-top:4px;padding:2px 8px;border-radius:var(--pill);font-style:normal;font-size:.68rem;font-weight:800;background:var(--dk-tint-err, #FDECEC);color:var(--dk-txt-err, #B02E2E)}
.mkm-type{display:inline-flex;padding:3px 9px;border-radius:var(--pill);font-size:.72rem;font-weight:700;white-space:nowrap;background:var(--b100);color:var(--dk-acc-strong, var(--b700))}
.mkm-type--yurist{background:var(--dk-tint-violet, #EFEAFE);color:var(--dk-txt-violet, #5B3CC4)}
.mkm-type--advokat_tashkiloti{background:var(--dk-tint-ok, #E1F6EE);color:var(--dk-txt-ok, #0B7A55)}
.mkm-rate{display:flex;align-items:center;gap:4px;font-weight:700;white-space:nowrap}
.mkm-rate svg{width:14px;height:14px;fill:#F4B63F;color:#F4B63F}
.mkm-rate small{display:inline!important;margin:0 0 0 4px!important}
.mkm-ver{display:flex;width:max-content;align-items:center;gap:4px;margin-top:4px;font-size:.74rem;font-weight:700;white-space:nowrap}
.mkm-ver svg{width:13px;height:13px}
.mkm-ver--ok{color:var(--dk-txt-ok, #0A6B0A)}
.mkm-ver--wait{color:var(--dk-txt-warn, #875000)}
.mkm-ver--bad{color:var(--dk-txt-err, #B02E2E)}
.mkm-ver--none{color:var(--gray)}
.mkm-load{display:flex;align-items:center;gap:8px;min-width:96px}
.mkm-load b{min-width:20px;text-align:right;font-family:var(--fd);font-size:1.05rem}
.mkm-load>span{flex:1;height:8px;border-radius:4px;background:var(--dk-surface-2, #EEF2F8);overflow:hidden}
.mkm-load i{display:block;height:100%;border-radius:0 4px 4px 0;background:var(--mkm-active)}
.mkm-load.is-zero b{color:var(--gray2)}
.mkm-pager{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;font-size:.84rem;font-weight:600;color:var(--gray);font-variant-numeric:tabular-nums}
.mkm-pager div{display:flex;gap:8px}
.mkm-pager .btn svg{width:15px;height:15px}

.mkm-det{display:flex;flex-direction:column;gap:16px}
.mkm-ticket{position:relative;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:12px 20px;padding:20px;border-radius:20px;background:var(--grad-dark);color:#fff;overflow:hidden;overflow:clip;isolation:isolate}
.mkm-ticket::before{content:"";position:absolute;top:-80%;right:-10%;width:60%;height:220%;background:radial-gradient(closest-side,rgba(0,207,232,.32),transparent);z-index:-1;pointer-events:none}
.mkm-ticket__badges{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:6px}
.mkm-ticket .mkm-pay{background:rgba(255,255,255,.12);color:#fff;box-shadow:inset 0 0 0 1px rgba(255,255,255,.28)}
.mkm-ticket__main{min-width:0}
.mkm-ticket h3{margin:0;font-family:var(--fd);font-size:1.22rem;line-height:1.25;letter-spacing:-.02em;overflow-wrap:anywhere}
.mkm-ticket__main p{margin:4px 0 0;font-size:.86rem;color:rgba(255,255,255,.75)}
.mkm-ticket__sum{text-align:right;white-space:nowrap}
.mkm-ticket__sum b{display:block;font-family:var(--fd);font-size:1.8rem;letter-spacing:-.03em;line-height:1}
.mkm-ticket__sum small{font-size:.8rem;font-weight:700;color:rgba(255,255,255,.72)}
.mkm-ids{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:8px;margin:0}
.mkm-ids div{display:flex;align-items:center;gap:6px;padding:5px 10px;border-radius:10px;background:rgba(255,255,255,.1)}
.mkm-ids dt{font-size:.64rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:rgba(255,255,255,.62)}
.mkm-ids dd{margin:0;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.8rem;font-weight:700}

.mkm-journey{list-style:none;margin:0;padding:4px 0 0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}
.mkm-journey li{position:relative;display:flex;flex-direction:column;align-items:center;gap:5px;padding:0 6px;text-align:center}
.mkm-journey li::before{content:"";position:absolute;top:15px;left:calc(-50% + 22px);right:calc(50% + 22px);height:2px;border-radius:2px;background:var(--line)}
.mkm-journey li:first-child::before{display:none}
.mkm-journey li.is-done::before{background:var(--mkm-done)}
.mkm-journey li.is-now::before{background:linear-gradient(90deg,var(--mkm-done),var(--mkm-j, var(--mkm-active)))}
.mkm-journey li.is-fail::before{background:var(--mkm-cancel)}
.mkm-jt--pending{--mkm-j:var(--mkm-pending)}
.mkm-jt--active{--mkm-j:var(--mkm-active)}
.mkm-journey__c{position:relative;z-index:1;display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:var(--dk-surface-2, #EEF3FB);color:var(--gray2);box-shadow:0 0 0 4px var(--dk-surface, #fff)}
.mkm-journey__c svg{width:15px;height:15px}
.mkm-journey li.is-done .mkm-journey__c{background:var(--mkm-done);color:#fff}
.mkm-journey li.is-now .mkm-journey__c{background:var(--mkm-j, var(--mkm-active));color:#fff;animation:mkm-ping 2s infinite}
.mkm-journey li.is-now.mkm-jt--pending .mkm-journey__c{color:#3A2600}
.mkm-journey li.is-fail .mkm-journey__c{background:var(--mkm-cancel);color:#fff}
.mkm-journey b{font-size:.8rem;line-height:1.3;color:var(--ink)}
.mkm-journey li.is-todo b{color:var(--gray2)}
.mkm-journey small{font-size:.72rem;color:var(--gray);line-height:1.3}

.mkm-det__cols{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,1fr);gap:14px;align-items:start}
.mkm-det__col{display:flex;flex-direction:column;gap:14px;min-width:0}
.mkm-sec{display:flex;flex-direction:column;gap:10px;min-width:0;padding:14px;border-radius:18px;background:var(--dk-surface-2, #F7FAFE)}
.mkm-sec h4{margin:0;display:flex;align-items:center;gap:8px;font-family:var(--fd);font-size:.95rem;color:var(--ink)}
.mkm-sec h4 svg{width:16px;height:16px;color:var(--dk-acc, var(--b600))}
.mkm-people{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.mkm-person{display:flex;flex-direction:column;align-items:flex-start;gap:8px;min-width:0;padding:12px;border-radius:14px;background:var(--dk-surface, #fff);box-shadow:inset 0 0 0 1px var(--line)}
.mkm-person__top{display:flex;align-items:center;gap:10px;min-width:0;width:100%}
.mkm-person__top>div{display:flex;flex-direction:column;min-width:0}
.mkm-person__role{font-size:.64rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--gray2)}
.mkm-person b{font-size:.92rem;color:var(--ink);overflow-wrap:anywhere}
.mkm-person__meta{display:flex;flex-wrap:wrap;font-size:.75rem;color:var(--gray)}
.mkm-person a{display:inline-flex;align-items:center;gap:6px;font-size:.84rem;font-weight:600;color:var(--dk-acc, var(--b600))}
.mkm-person a svg{width:14px;height:14px}
.mkm-dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 16px;margin:0}
.mkm-dl>div{min-width:0}
.mkm-dl .is-wide{grid-column:1/-1}
.mkm-dl dt{font-size:.66rem;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:var(--gray2)}
.mkm-dl dd{margin:3px 0 0;font-size:.88rem;font-weight:600;color:var(--ink);overflow-wrap:anywhere}
.mkm-note{margin:0;padding:10px 12px;border-radius:12px;background:var(--dk-surface, #fff);font-size:.88rem;line-height:1.5;white-space:pre-line;color:var(--ink)}
.mkm-note small{display:block;margin-bottom:2px;font-size:.66rem;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:var(--gray2)}
.mkm-contact{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.mkm-contact .btn svg{width:15px;height:15px}
.mkm-chip{display:inline-flex;align-items:center;gap:6px;padding:7px 12px;border-radius:var(--pill);font-size:.78rem;font-weight:700;background:var(--dk-surface, #fff);box-shadow:inset 0 0 0 1px var(--line);color:var(--gray)}
.mkm-chip svg{width:14px;height:14px}
.mkm-chip--on{color:var(--dk-txt-ok, #0A6B0A)}
.mkm-code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.8rem;font-weight:700}

.mkm-tg{display:flex;flex-direction:column;gap:12px;padding:14px;border-radius:16px;background:var(--dk-surface, #fff);box-shadow:inset 0 0 0 1px var(--line)}
.mkm-tg--done{box-shadow:inset 0 0 0 1px var(--dk-bd-ok, rgba(12,163,12,.3))}
.mkm-tg--cancel{box-shadow:inset 0 0 0 1px var(--dk-bd-err, rgba(208,59,59,.3))}
.mkm-tg__h{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.mkm-tg__ic{flex:none;display:grid;place-items:center;width:30px;height:30px;border-radius:10px;background:linear-gradient(135deg,#2AABEE,#229ED9);color:#fff}
.mkm-tg__ic svg{width:15px;height:15px}
.mkm-tg__h em{margin-left:auto;font-style:normal;font-size:.78rem;color:var(--gray)}
.mkm-deliv{display:flex;flex-direction:column;gap:8px}
.mkm-deliv>span{font-size:.8rem;font-weight:700;color:var(--gray)}
.mkm-deliv ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.mkm-deliv li{display:inline-flex;align-items:center;gap:5px;padding:4px 9px;border-radius:9px;font-size:.74rem;font-weight:700;background:var(--dk-surface-2, #F2F6FC);color:var(--ink)}
.mkm-deliv li svg{width:12px;height:12px}
.mkm-deliv li.ok svg{color:var(--mkm-done)}
.mkm-deliv li.bad{background:var(--dk-tint-err, #FDECEC);color:var(--dk-txt-err, #B02E2E)}
.mkm-deliv li.is-rev{box-shadow:inset 0 0 0 1.5px var(--mkm-done)}
.mkm-deliv code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.74rem}
.mkm-deliv li em{font-style:normal;font-size:.62rem;font-weight:800;letter-spacing:.04em;text-transform:uppercase;color:var(--dk-txt-ok, #0A6B0A)}

.mkm-tl{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.mkm-tl li{position:relative;display:flex;gap:12px;padding:0 0 14px}
.mkm-tl li::before{content:"";position:absolute;left:5px;top:16px;bottom:0;width:2px;background:var(--line)}
.mkm-tl li:last-child{padding-bottom:0}
.mkm-tl li:last-child::before{display:none}
.mkm-tl__dot{position:relative;z-index:1;flex:none;width:12px;height:12px;margin-top:4px;border-radius:50%;background:var(--mkm-done);box-shadow:0 0 0 3px var(--dk-surface-2, #F7FAFE)}
.mkm-tl li.is-bad .mkm-tl__dot{background:var(--mkm-cancel)}
.mkm-tl li.is-na .mkm-tl__dot{background:var(--gray2)}
.mkm-tl li>div{display:flex;flex-direction:column;gap:2px;min-width:0}
.mkm-tl b{font-size:.88rem;color:var(--ink)}
.mkm-tl span{font-size:.82rem;color:var(--gray);overflow-wrap:anywhere}
.mkm-tl em{font-style:normal;font-size:.74rem;color:var(--gray2)}

@media (max-width:1180px){
  .mkm-grid{grid-template-columns:minmax(0,1fr)}
  .mkm-latest__row{grid-template-columns:10px 96px minmax(0,1fr) auto auto}
  .mkm-latest__when{display:none}
}
@media (max-width:900px){
  .mkm-det__cols{grid-template-columns:minmax(0,1fr)}
  .mkm-table--orders,.mkm-table--sellers{min-width:0}
  .mkm-tablewrap{overflow:visible;margin:0;padding:0}
  .mkm-table--orders thead,.mkm-table--sellers thead{display:none}
  .mkm-table--orders,.mkm-table--sellers,.mkm-table--orders tbody,.mkm-table--sellers tbody{display:block}
  .mkm-table--orders tr,.mkm-table--sellers tr{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 14px;padding:14px;margin-bottom:10px;border-radius:16px;background:var(--dk-surface, #fff);box-shadow:inset 0 0 0 1px var(--line)}
  .mkm-table--orders td,.mkm-table--sellers td{display:block;min-width:0;padding:0;border:0}
  .mkm-table--orders td[data-l]::before,.mkm-table--sellers td[data-l]::before{content:attr(data-l);display:block;margin-bottom:3px;font-size:.64rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--gray2)}
  .mkm-table--orders td.num,.mkm-table--sellers td.num{text-align:left}
  .mkm-table--orders .mkm-td--id::before{display:none!important}
  .mkm-td--wide{grid-column:1/-1}
  .mkm-tr__go{display:none!important}
  .mkm-tr:hover td{background:transparent}
  .mkm-clamp{max-width:none}
  .mkm-td--who{white-space:normal}
  .mkm-seller{min-width:0}
  .mkm-load{min-width:0}
}
@media (max-width:760px){
  .mkm-kpis{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
  .mkm-kpi{padding:14px}
  .mkm-kpi__v{font-size:1.4rem}
  .mkm-rev{width:100%}
  .mkm-hero__bar{margin-top:18px}
  .mkm-latest__row{grid-template-columns:10px minmax(0,1fr) auto;grid-template-areas:"dot id st" "dot svc svc" "dot amt amt";row-gap:6px}
  .mkm-latest__row>.mkm-dot{grid-area:dot;align-self:start;margin-top:5px}
  .mkm-latest__row>.mkm-wid{grid-area:id}
  .mkm-latest__row>.mkm-st{grid-area:st;justify-self:end}
  .mkm-latest__svc{grid-area:svc}
  .mkm-latest__amt{grid-area:amt}
  .mkm-people,.mkm-dl{grid-template-columns:minmax(0,1fr)}
  .mkm-ticket{grid-template-columns:minmax(0,1fr)}
  .mkm-ticket__sum{text-align:left}
}
@media (max-width:560px){
  .mkm-tabs{flex:1}
  .mkm-tab{flex:1 1 0;justify-content:center;padding:8px 6px;font-size:.8rem}
  .mkm-tab span{display:none}
  .mkm-legend{grid-template-columns:minmax(0,1fr)}
  .mkm-journey{grid-template-columns:minmax(0,1fr);gap:12px;padding:0}
  .mkm-journey li{flex-direction:row;align-items:center;gap:10px;text-align:left;padding:0}
  .mkm-journey li::before{left:15px;right:auto;top:-12px;width:2px;height:12px}
  .mkm-journey small{margin-left:auto;text-align:right}
}
@media (prefers-reduced-motion:reduce){
  .mkm-hero__glow,.mkm-live,.mkm-journey__c,.mkm-kpi--ghost{animation:none}
  .mkm-kpi--btn:hover{transform:none}
}
.mtg__bgwrap{position:absolute;inset:0;z-index:45;display:flex;align-items:flex-end;justify-content:center;padding:0 16px 104px;pointer-events:none;animation:mtgIn .2s ease}
.mtg__bgpanel{width:min(640px,100%);max-height:min(660px,calc(100% - 150px));overflow-y:auto;overscroll-behavior:contain;display:flex;flex-direction:column;gap:14px;padding:16px 16px 14px;border-radius:20px;background:var(--b850);border:1px solid var(--mtg-line);box-shadow:0 30px 80px -20px rgba(0,0,0,.65);outline:none;scrollbar-width:thin;color:#fff;pointer-events:auto}
.mtg__bggrip{display:none;flex:none;width:38px;height:4px;margin:2px auto 0;border-radius:999px;background:rgba(255,255,255,.25)}
.mtg__bgh{display:flex;align-items:center;justify-content:space-between;gap:10px}
.mtg__bgh b{font-family:var(--fd);font-size:1.02rem;letter-spacing:-.01em}
.mtg__bgx{display:grid;place-items:center;flex:none;width:32px;height:32px;border:0;border-radius:10px;background:rgba(255,255,255,.08);color:#cbd5e1;cursor:pointer;transition:background .15s,color .15s}
.mtg__bgx:hover{background:rgba(255,255,255,.14);color:#fff}
.mtg__bgx:focus-visible{outline:2px solid var(--b400);outline-offset:2px}
.mtg__bgx svg{width:16px;height:16px}
.mtg__bgnote{margin:0;padding:8px 12px;border-radius:12px;background:rgba(251,193,94,.12);color:#FBC15E;font-size:.82rem;line-height:1.45}
.mtg__bgsec{display:flex;flex-direction:column;gap:8px}
.mtg__bgcap{font-size:.68rem;font-weight:800;letter-spacing:.07em;text-transform:uppercase;color:rgba(255,255,255,.55)}
.mtg__bgrow{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.mtg__bggrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.mtg__bgopt{position:relative;display:flex;flex-direction:column;gap:5px;min-width:0;width:100%;padding:0;border:0;background:none;color:#cbd5e1;font:inherit;text-align:left;cursor:pointer}
.mtg__bgopt:focus-visible{outline:none}
.mtg__bgpic{position:relative;display:grid;place-items:center;aspect-ratio:16/9;border-radius:12px;overflow:hidden;background:rgba(255,255,255,.06);box-shadow:inset 0 0 0 1px rgba(255,255,255,.1);transition:box-shadow .15s,transform .15s}
.mtg__bgpic img{width:100%;height:100%;object-fit:cover;display:block}
.mtg__bgopt:hover .mtg__bgpic{box-shadow:inset 0 0 0 2px rgba(255,255,255,.35)}
.mtg__bgopt:active .mtg__bgpic{transform:scale(.97)}
.mtg__bgopt:focus-visible .mtg__bgpic{outline:2px solid #fff;outline-offset:2px}
.mtg__bgopt[aria-pressed=true]{color:#fff}
.mtg__bgopt[aria-pressed=true] .mtg__bgpic{box-shadow:inset 0 0 0 3px var(--b400),0 8px 22px -10px rgba(92,168,255,.9)}
.mtg__bglbl{font-size:.74rem;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mtg__bgblur{transform:scale(1.18)}
.mtg__bgblur--light{filter:blur(1.6px)}
.mtg__bgblur--strong{filter:blur(4.5px)}
.mtg__bgslash{position:relative;width:26px;height:26px;border-radius:50%;box-shadow:inset 0 0 0 2px rgba(255,255,255,.6)}
.mtg__bgslash::after{content:"";position:absolute;left:50%;top:-1px;bottom:-1px;width:2px;border-radius:2px;background:rgba(255,255,255,.6);transform:translateX(-50%) rotate(45deg)}
.mtg__bgup .mtg__bgpic{background:rgba(92,168,255,.08);box-shadow:none;border:1.5px dashed rgba(92,168,255,.55)}
.mtg__bgup:hover .mtg__bgpic{box-shadow:none;border-color:var(--b300);background:rgba(92,168,255,.14)}
.mtg__bgup .mtg__bgpic svg{width:22px;height:22px;color:var(--b300)}
.mtg__bgup:disabled{cursor:progress}
.mtg__bgcustom{position:relative;min-width:0}
.mtg__bgdel{position:absolute;top:6px;right:6px;z-index:1;display:grid;place-items:center;width:26px;height:26px;border:0;border-radius:8px;background:rgba(4,12,31,.72);color:#fff;cursor:pointer;transition:background .15s}
.mtg__bgdel:hover{background:#E5484D}
.mtg__bgdel:focus-visible{outline:2px solid #fff;outline-offset:1px}
.mtg__bgdel svg{width:14px;height:14px}
.mtg__bgspin{position:absolute;inset:0;display:grid;place-items:center;background:rgba(4,12,31,.45)}
.mtg__bgspin::after{content:"";width:22px;height:22px;border-radius:50%;border:2.5px solid rgba(255,255,255,.3);border-top-color:#fff;animation:mk-spin .8s linear infinite}
.mtg__bgerr{margin:0;padding:8px 12px;border-radius:12px;background:rgba(229,72,77,.14);color:#FF9494;font-size:.82rem;line-height:1.45}
.mtg__bgfoot{margin:0;font-size:.74rem;color:rgba(255,255,255,.5);text-align:center}
@media (max-width:760px){
  .mtg__bgwrap{padding:0;pointer-events:auto;background:rgba(3,16,43,.45);backdrop-filter:blur(2px)}
  .mtg__bgpanel{width:100%;max-height:84%;border-radius:20px 20px 0 0;border-width:1px 0 0;padding:6px 14px calc(14px + env(safe-area-inset-bottom));animation:mtgSheet .25s ease}
  .mtg__bggrip{display:block}
  .mtg__bggrid{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@media (min-width:761px) and (max-height:560px){
  .mtg__bgwrap{padding:0 16px;pointer-events:auto;background:rgba(3,16,43,.45);backdrop-filter:blur(2px)}
  .mtg__bgpanel{max-height:92%;border-radius:20px 20px 0 0;border-bottom-width:0;padding-bottom:calc(14px + env(safe-area-inset-bottom))}
}
@media (min-width:761px) and (max-width:1000px){
  .mtg:not(.mtg--float) .mtg__bar{flex-wrap:wrap;row-gap:2px}
  .mtg:not(.mtg--float) .mtg__bar>.mtg__ctl{flex:1 1 72px;max-width:max-content}
}
.mtg:has(.mtg__bgwrap) .mtg__toasts{z-index:46}
.mtg__moresheet{max-height:100%;overflow-y:auto;overscroll-behavior:contain}
@media (prefers-reduced-motion:reduce){
  .mtg__bgwrap,.mtg__bgpanel{animation:none}
  .mtg__bgopt:active .mtg__bgpic{transform:none}
}

/* ── Legal agent answers (components/chat/AgentAnswer.tsx) ─────────────
   Markdown answers built from lex.uz articles: a "Qisqa javob" lead, numbered
   rules with verbatim quotes, inline article citations and a sources block. */
.ag{display:flex;flex-direction:column;gap:12px;font-size:.97rem;line-height:1.7;color:var(--ink);min-width:0;overflow-wrap:anywhere}
.ag p{margin:0}
.ag strong{font-weight:700;color:var(--ink)}
.ag code{font-size:.88em;background:var(--b50);padding:1px 6px;border-radius:6px}
.ag-lead{position:relative;padding:14px 16px 14px 18px;border-radius:14px;background:linear-gradient(135deg,var(--b50),var(--dk-surface-2, #F7FBFF));
  box-shadow:inset 0 0 0 1px var(--b200);overflow:hidden}
.ag-lead::before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--grad)}
.ag-lead__lbl{display:inline-flex;align-items:center;gap:6px;font-size:.68rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;
  color:var(--dk-acc, var(--b600));margin-bottom:4px}
.ag-lead__lbl::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--dk-acc, var(--b600))}
.ag-lead p{font-size:1rem;line-height:1.65}
.ag-h{margin:6px 0 -2px;font-family:var(--fd);font-size:.98rem;font-weight:700;letter-spacing:-.01em;color:var(--ink);display:flex;align-items:center;gap:10px}
.ag-h::after{content:"";flex:1;height:1px;background:var(--line)}

.ag-list{margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:12px}
.ag-list > li{position:relative;padding-left:24px}
.ag-list > li::before{content:"";position:absolute;left:7px;top:.72em;width:6px;height:6px;border-radius:50%;background:var(--b400)}
.ag-list--ol{counter-reset:ag}
.ag-list--ol > li{counter-increment:ag;padding-left:38px}
.ag-list--ol > li::before{content:counter(ag);left:0;top:.1em;width:26px;height:26px;border-radius:8px;background:var(--b100);
  color:var(--dk-acc-strong, var(--b700));font:700 .78rem/26px var(--fd);text-align:center}
.ag-list--sub{margin-top:6px;gap:4px}
.ag-list--sub > li{padding-left:18px}
.ag-list--sub > li::before{left:4px;width:5px;height:5px;background:var(--gray2)}
.ag-li + .ag-q,.ag-q + .ag-li{margin-top:8px}

.ag-q{margin:0;position:relative;padding:10px 14px 10px 34px;border-radius:0 12px 12px 0;border-left:3px solid var(--b300);
