.acite__n{font-size:.68em;font-weight:800;min-width:15px;height:15px;line-height:15px;padding:0 4px;border-radius:5px;text-align:center;
  background:var(--b600);color:#fff;align-self:center;top:0;vertical-align:baseline}
.alink{color:var(--dk-acc, var(--b600));text-decoration:underline;text-underline-offset:2px}

.ag-note{display:flex;gap:10px;align-items:flex-start;padding:10px 13px;border-radius:12px;font-size:.86rem;line-height:1.55;
