.ag-note svg{width:17px;height:17px;flex:none;margin-top:2px}
.ag-foot{display:flex;gap:8px;align-items:flex-start;padding-top:10px;border-top:1px dashed var(--line);font-size:.76rem;line-height:1.5;color:var(--gray2)}
