@keyframes lpromoIn{0%{opacity:0;transform:translateX(calc(100% + 40px)) rotate(4deg)}60%{opacity:1}100%{opacity:1;transform:none}}
@keyframes lpromoOut{to{opacity:0;transform:translateX(calc(100% + 40px))}}
@keyframes lpromoUp{0%{opacity:0;transform:translateY(calc(100% + 30px))}100%{opacity:1;transform:none}}
@keyframes lpromoDown{to{opacity:0;transform:translateY(calc(100% + 30px))}}
.lpromo__shine{position:absolute;inset:0;z-index:-1;background:linear-gradient(105deg,transparent 35%,rgba(255,255,255,.2) 50%,transparent 65%);transform:translateX(-120%);animation:lpromoShine 5.5s ease-in-out 1.2s infinite;pointer-events:none}
@keyframes lpromoShine{0%,60%{transform:translateX(-120%)}85%,100%{transform:translateX(120%)}}
.lpromo__link{display:flex;align-items:center;gap:14px;padding:16px 42px 16px 14px;color:inherit;text-decoration:none}
.lpromo__link:focus-visible{outline:3px solid var(--cy);outline-offset:-3px;border-radius:22px}
.lpromo__art{position:relative;flex:none;width:96px;height:96px;display:grid;place-items:center}
.lpromo__halo{position:absolute;inset:6px;border-radius:50%;background:radial-gradient(circle,rgba(120,220,255,.55),rgba(120,220,255,0) 70%);animation:lpromoPulse 2.6s ease-in-out infinite}
.lpromo__art img{position:relative;width:96px;height:96px;object-fit:contain;filter:drop-shadow(0 10px 16px rgba(0,20,60,.45));animation:lpromoFloat 4.2s ease-in-out infinite}
.lpromo__badge{position:absolute;right:-2px;bottom:4px;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#22c55e;color:#fff;box-shadow:0 0 0 3px #0f3f86,0 6px 14px -4px rgba(0,0,0,.5);animation:lpromoPop .5s .8s cubic-bezier(.2,1.6,.4,1) both}
.lpromo__badge svg{width:15px;height:15px}
@keyframes lpromoPulse{0%,100%{transform:scale(.9);opacity:.7}50%{transform:scale(1.06);opacity:1}}
@keyframes lpromoFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}
@keyframes lpromoPop{from{transform:scale(0)}to{transform:scale(1)}}
.lpromo__copy{display:flex;flex-direction:column;gap:5px;min-width:0}
.lpromo__tag{display:inline-flex;align-self:flex-start;align-items:center;gap:5px;padding:3px 9px;border-radius:999px;background:rgba(255,255,255,.16);font-size:.7rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase}
.lpromo__tag svg{width:12px;height:12px;color:#ffd166}
.lpromo__copy strong{font-family:var(--fd);font-size:1.06rem;line-height:1.2;letter-spacing:-.02em}
.lpromo__text{font-size:.8rem;line-height:1.35;color:rgba(255,255,255,.82)}
.lpromo__cta{display:inline-flex;align-self:flex-start;align-items:center;gap:6px;margin-top:4px;padding:7px 13px;border-radius:999px;background:#fff;color:#0b3d91;font-size:.8rem;font-weight:800;transition:transform .15s,gap .15s}
.lpromo__cta svg{width:14px;height:14px}
.lpromo__link:hover .lpromo__cta{gap:10px;transform:translateX(2px)}
.lpromo__x{position:absolute;top:10px;right:10px;z-index:2;width:28px;height:28px;border:0;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.14);color:#fff;cursor:pointer;transition:background .15s}
.lpromo__x:hover{background:rgba(255,255,255,.28)}
.lpromo__x svg{width:14px;height:14px}
@media (max-width:900px){.lpromo{top:auto;right:12px;left:12px;bottom:calc(12px + env(safe-area-inset-bottom));width:auto}.lpromo--in{animation-name:lpromoUp}.lpromo--out{animation-name:lpromoDown}}
@media (max-width:420px){.lpromo__art,.lpromo__art img{width:72px;height:72px}.lpromo__text{display:none}}
@media (prefers-reduced-motion:reduce){.lpromo--in,.lpromo--out{animation-duration:.01ms}.lpromo__shine,.lpromo__halo,.lpromo__art img,.lpromo__badge{animation:none}}

.psup{position:relative}
.psup__btn{position:relative;width:40px;height:40px;border-radius:12px;border:1px solid var(--line);background:var(--dk-surface,#fff);color:var(--dk-acc,var(--b600));display:grid;place-items:center;cursor:pointer;transition:border-color .15s,transform .15s}
