@keyframes psupWiggle{0%,86%,100%{transform:rotate(0)}88%{transform:rotate(-14deg)}90%{transform:rotate(12deg)}92%{transform:rotate(-9deg)}94%{transform:rotate(6deg)}96%{transform:rotate(0)}}
