:root{--gd-ring:#1668F0;--gd-ring2:rgba(255,255,255,.95);--gd-glow:rgba(0,166,230,.55);--gd-scrim:rgba(3,16,43,.42);--gd-scrim-solid:rgba(3,16,43,.62);--gd-cap:#03102B;--gd-caret:#00CFE8}
